window.TXB=window.TXB||{};TXB["alab/Jdg"]={"1:1":"بعد موت يشوع سأل بنو إسرائيل الرب: «من منا يذهب أولا لمحاربة الكنعانيين؟»","1:2":"فأجاب الرب: «يهوذا يذهب، فقد أسلمت الأرض إلى يده».","1:3":"فقال رجال يهوذا لإخوتهم رجال شمعون: «اخرجوا معنا إلى المنطقة التي صارت قرعة لنا لنحارب الكنعانيين معا، ثم نخرج نحن معكم في حربكم لتستولوا على قرعتكم». فذهب رجال شمعون معهم.","1:4":"فانطلق رجال يهوذا لخوض الحرب، فأظفرهم الرب بالكنعانيين والفرزيين، فقتلوا منهم في بازق عشرة آلاف رجل.","1:5":"والتقوا بملكهم أدوني بازق عند بازق، فحاربوه وقهروا الكنعانيين والفرزيين.","1:6":"فهرب أدوني بازق، غير أنهم تعقبوه وقبضوا عليه وقطعوا أباهم يديه ورجليه.","1:7":"فقال أدوني بازق: «لقد قطعت أباهم أيدي وأرجل سبعين ملكا كانوا يلتقطون الفتات تحت مائدتي، فها الرب قد جازاني بمثل ما فعلت». وأتوا به إلى أورشليم حيث مات.","1:8":"وكان أبناء يهوذا قد هاجموا أورشليم واستولوا عليها، وقتلوا أهلها بحد السيف وأحرقوها بالنار.","1:9":"ثم انحدروا لمحاربة الكنعانيين في المناطق الجبلية والنقب والسهول الغربية.","1:10":"فهاجموا الكنعانيين المقيمين في حبرون التي كانت تدعى قبلا قرية أربع، وقضوا على شيشاي وأخيمان وتلماي.","1:11":"وتوجهوا من هناك وانقضوا على أهل دبير التي كانت تدعى قبلا قرية سفر.","1:12":"فقال كالب: «الذي يقهر قرية سفر ويستولي عليها، أزوجه ابنتي عكسة».","1:13":"فاستولى عليها عثنيئيل بن قناز، أخو كالب الأصغر منه، فزوجه ابنته عكسة.","1:14":"وعندما زفت إليه حثها على طلب حقل من أبيها، فترجلت عن الحمار، فسألها كالب: «مالك؟»","1:15":"فقالت له: «أنعم علي بهبة، فأنت قد أعطيتني أرضا في النقب، فأعطني أيضا ينابيع ماء». فوهبها كالب الينابيع العليا والينابيع السفلى.","1:16":"وغادر أبناء القيني حمي موسى مدينة النخل (أريحا) وذهبوا مع سبط يهوذا إلى برية يهوذا الواقعة في جنوبي عراد، وسكنوا مع الشعب.","1:17":"وانضم جيش يهوذا إلى جيش شمعون، وحاربوا الكنعانيين أهل صفاة ودمروها ودعوا اسم المدينة حرمة (بمعنى خراب).","1:18":"واستولى رجال يهوذا على غزة وتخومها وأشقلون وتخومها وعقرون وتخومها.","1:19":"وكان الرب مع أبناء يهوذا فتملكوا الجبل، ولكنهم أخفقوا في طرد سكان الوادي لأنهم كانوا يملكون مركبات حديدية.","1:20":"وأعطوا حبرون لكالب كما أوصى موسى، فطرد منها بني عناق الثلاثة.","1:21":"وأخفق أبناء بنيامين في طرد اليبوسيين سكان أورشليم، فظل اليبوسيون يقيمون بين ذرية بنيامين في أورشليم إلى هذا اليوم.","1:22":"وهاجم أبناء سبط يوسف بيت إيل، فكان الرب معهم (ونصرهم).","1:23":"وبينما كان فريق الاستكشاف يراقب بيت إيل، التي كانت تدعى قبلا لوز،","1:24":"شاهدوا رجلا خارجا من المدينة (فقبضوا عليه) وقالوا له: «أرشدنا إلى مدخل المدينة فنصنع معك معروفا».","1:25":"فأرشدهم إلى مدخل المدينة، فاقتحموها وقضوا على أهلها بحد السيف، أما الرجل وسائر عشيرته فأطلقوهم.","1:26":"فمضى الرجل إلى ديار الحثيين وبنى مدينة دعاها لوز، وهذا هو اسمها حتى الآن.","1:27":"وأخفق أبناء سبط منسى في طرد أهل بيت شان وقراها، وأهل تعنك وقراها، وسكان دور وقراها، وسكان يبلعام وقراها، وسكان مجدو وقراها. فاستمر الكنعانيون يسكنون فيها.","1:28":"ولما قويت شوكة الإسرائيليين وضعوا الكنعانيين تحت الجزية، ولم يطردوهم قط.","1:29":"وكذلك فشل سبط أفرايم في طرد الكنعانيين الساكنين في جازر، فسكن الكنعانيون معهم.","1:30":"ولم يطرد أبناء زبولون الكنعانيين المستوطنين في قطرون ونهلول، فأقام الكنعانيون بينهم، وفرضوا عليهم الجزية.","1:31":"وأيضا لم يطرد أبناء سبط أشير سكان عكو ولا سكان صيدون وأحلب وأكزيب وحلبة وأفيق ورحوب.","1:32":"فسكن الأشيريون في وسط الكنعانيين أهل الأرض لأنهم لم يطردوهم.","1:33":"ولم يطرد أبناء سبط نفتالي سكان بيت شمس وبيت عناة بل أقاموا في وسط الكنعانيين أهل الأرض، وفرضوا عليهم الجزية.","1:34":"وحصر الأموريون أبناء دان في الجبل ولم يسمحوا لهم بالنزول إلى الوادي.","1:35":"وعزم الأموريون على الإقامة في جبل حارس وفي أيلون وفي شعلبيم. ولكن عندما قويت شوكة سبط يوسف فرضوا عليهم الجزية.","1:36":"وكانت حدود الأموريين تمتد من عقبة عقربيم من سالع إلى ما وراءها.","2:1":"واجتاز ملاك الرب من الجلجال إلى بوكيم وقال: «لقد أخرجتكم من مصر وجئت بكم إلى الأرض التي حلفت أن أهبها لآبائكم، وقلت: لا أنقض عهدي معكم إلى الأبد،","2:2":"وأمرتكم أن لا تقطعوا عهدا مع أهل هذه الأرض، وأن تهدموا مذابحهم. غير أنكم لم تطيعوا صوتي. فلماذا فعلتم هذا؟","2:3":"لذلك قلت أيضا: لا أطردهم من أمامكم، فيصبحوا شوكا في جنوبكم، وتكون آلهتهم لكم شركا».","2:4":"فما إن نطق ملاك الرب بهذا الكلام أمام جميع بني إسرائيل حتى رفع الشعب صوته بالبكاء.","2:5":"ودعوا اسم ذلك الموضع بوكيم (ومعناه: الباكون) وقدموا هناك ذبائح للرب.","2:6":"وصرف يشوع الشعب، فمضى كل واحد من بني إسرائيل لامتلاك ميراثه.","2:7":"وظل الشعب يعبد الرب طوال حياة يشوع، وكل أيام الشيوخ الذين عمروا طويلا بعد موته، والذين شهدوا كل المعجزات الخارقة التي أجراها الرب من أجل بني إسرائيل.","2:8":"ومات يشوع بن نون عبد الرب وقد بلغ من العمر مئة وعشر سنوات،","2:9":"فدفنوه في حدود أملاكه في تمنة حارس في جبل أفرايم شمالي جبل جاعش.","2:10":"وكذلك مات أيضا كل جيل يشوع، وأعقبهم جيل آخر لم يعرف الرب ولا كل أعماله التي أجراها من أجل إسرائيل.","2:11":"واقترف بنو إسرائيل الشر في عيني الرب وعبدوا البعليم،","2:12":"ونبذوا الرب إله آبائهم الذي أخرجهم من ديار مصر، وغووا وراء آلهة أخرى من أوثان الشعوب المحيطة بهم، وسجدوا لها، فأغاظوا الرب.","2:13":"تركوا الرب وعبدوا البعل وعشتاروث.","2:14":"فاحتدم غضب الرب على إسرائيل وتركهم تحت رحمة الناهبين الغزاة. وأسلمهم إلى أعدائهم المحيطين بهم فعجزوا عن مقاومتهم.","2:15":"وحيثما خرجوا لخوض الحرب كان الرب ضدهم فينكسرون، تماما كما سبق وحذرهم، فاعتراهم ضيق عظيم جدا.","2:16":"وأقام الرب من بينهم قضاة فأنقذوهم من أيدي غزاتهم.","2:17":"غير أنهم عصوا قضاتهم أيضا، وخانوا الرب إذ عبدوا آلهة أخرى وسجدوا لها، وتحولوا سريعا عن الطريق التي سلكها آباؤهم إطاعة لوصايا الرب.","2:18":"وفي كل مرة كان الرب يقيم قاضيا كان يؤيده بقوة طوال حياته فيخلص الشعب من عبودية أعدائه إذ يشفق الرب عليهم مما يذيقهم مضايقوهم وظالموهم من عذاب؛ فكان الرب ينقذهم طوال حياة القاضي.","2:19":"ولكن ما إن يموت القاضي حتى يرتدوا عن الرب ويتفاقم فسادهم أكثر من تفاقم فساد آبائهم بالسعي وراء آلهة أخرى ليعبدوها ويسجدوا لها. لم يرتدعوا عن أفعالهم وسلوكهم العنيد.","2:20":"فاحتدم غضب الرب على إسرائيل وقال: «من حيث أن هذا الشعب قد نقض عهدي الذي عقدته مع آبائهم، وعصوني،","2:21":"فإني لن أطرد من أمامهم أي إنسان من الأمم الذين تركهم يشوع عند موته.","2:22":"بل سأبقي عليهم لأمتحن بهم إسرائيل، لأرى أيحفظون طريقي ليسلكوا فيها كما حفظها آباؤهم أم لا».","2:23":"وهكذا ترك الرب أولئك الأمم ولم يتعجل بطردهم ولم يخضعهم ليشوع.","3:1":"وهؤلاء هم الأمم الذين تركهم الرب ليختبر بهم بني إسرائيل الذين لم يخوضوا أي حرب من حروب أرض كنعان.","3:2":"وقد فعل هذا فقط ليدرب ذرية الإسرائيليين على الحرب، ممن لم يمارسوها من قبل.","3:3":"وهؤلاء الأمم هم: أقطاب الفلسطينيين الخمسة، وجميع الكنعانيين والصيدونيين والحويين سكان جبل لبنان، من جبل بعل حرمون إلى مدخل حماة.","3:4":"وقد أبقاهم الرب ليمتحن إسرائيل بهم: ليرى إن كانوا يطيعون أوامره التي أوصى بها آباءهم على لسان موسى.","3:5":"وأقام بنو إسرائيل بين الكنعانيين والأموريين والفرزيين والحويين واليبوسيين.","3:6":"وتزوجوا من بناتهم، وزوجوا بناتهم لأبنائهم وعبدوا آلهتهم.","3:7":"فارتكب بنو إسرائيل الشر في عيني الرب ونسوا إلههم وعبدوا البعليم والعشتاروث.","3:8":"فاحتدم غضب الرب عليهم، فسلط عليهم كوشان رشعتايم ملك أرام النهرين، فاستعبد كوشان رشعتايم بني إسرائيل ثماني سنوات.","3:9":"واستغاث بنو إسرائيل بالرب، فأقام لهم مخلصا أنقذهم هو عثنيئيل بن قناز أخو كالب الأصغر.","3:10":"فحل عليه روح الرب وصار قاضيا لإسرائيل. وحين خرج لمحاربة كوشان رشعتايم ملك أرام، تغلب عليه، وأظفره الرب به.","3:11":"وعم السلام البلاد حقبة أربعين سنة، إلى أن مات عثنيئيل بن قناز.","3:12":"فعاد بنو إسرائيل يقترفون الشر في عيني الرب فسلط الرب عليهم عجلون ملك موآب عقابا لهم على شرهم.","3:13":"فحشد ضدهم بني عمون وعماليق، وهاجمهم، واحتل أريحا مدينة النخل.","3:14":"واستعبد عجلون ملك موآب بني إسرائيل ثماني عشرة سنة.","3:15":"فاستغاث بنو إسرائيل بالرب، فأرسل لهم منقذا إهود بن جيرا البنياميني وكان أعسر، فبعث الإسرائيليون معه الجزية لعجلون ملك موآب.","3:16":"فصنع إهود لنفسه سيفا ذا حدين طوله ذراع (نحو نصف متر)، تقلده تحت ثيابه فوق فخذه اليمنى،","3:17":"وقدم الجزية لعجلون ملك موآب. وكان عجلون بدينا جدا.","3:18":"وبعد تقديم الجزية صرف إهود حامليها من القوم،","3:19":"ورجع هو من عند المحاجر المجاورة للجلجال، وقال للملك:","3:20":"«لدي كلام سر لأبلغك إياه أيها الملك». فصرف الملك كل الموجودين بمجلسه لينفرد بإهود","3:21":"فاقترب آنئذ منه إهود وهو جالس في عليته الخاصة، وقال له: «لدي لك رسالة من الله». فنهض الملك عن سريره. فمد عندئذ إهود يده اليسرى واستل سيفه عن فخذه اليمنى وأغمده في بطنه","3:22":"حتى غاص القائم وراء النصل فأطبق الشحم على النصل الذي اخترق ظهر الملك لأن إهود لم يجذب السيف من بطن الملك.","3:23":"وغادر إهود الرواق وأغلق خلفه أبواب العلية وأقفلها.","3:24":"وما لبث أن أقبل خدام الملك فوجدوا أبواب العلية مغلقة فقالوا: «لعله يقضي حاجته في العلية الصيفية».","3:25":"فلبثوا منتظرين حتى اعتراهم القلق لأنه لم يفتح أبواب المخدع فأخذوا مفتاحا وفتحوا الباب. وإذا سيدهم ساقط على الأرض ميتا.","3:26":"وفيما هم مبهوتون فر إهود واجتاز المحاجر ونجا إلى سعيرة.","3:27":"وما إن وصل إلى جبل أفرايم حتى نفخ بالبوق، فاجتمع خلفه بنو إسرائيل من الجبل، فسار في طليعتهم.","3:28":"وقال لهم: «اتبعوني لأن الرب قد دفع أعداءكم الموآبيين إلى أيديكم» فاحتشدوا وراءه واستولوا على مخاوض الأردن المفضية إلى موآب ومنعوا الأعداء من العبور.","3:29":"وهاجموا الموآبيين وقتلوا منهم نحو عشرة آلاف من المحاربين الأشداء.","3:30":"في ذلك اليوم خضع الموآبيون لبني إسرائيل، وعم السلام البلاد ثمانين سنة.","3:31":"وتولى شمجر بن عناة قضاء إسرائيل بعد إهود، فقتل ست مئة رجل من الفلسطينيين بمهماز بقر، وأنقذ إسرائيل.","4:1":"وبعد موت إهود عاد بنو إسرائيل يرتكبون الشر في عيني الرب،","4:2":"فأخضعهم الرب ليابين ملك كنعان المقيم في حاصور. وكان سيسرا رئيس جيشه قاطنا في حروشة الأمم.","4:3":"فاستغاث بنو إسرائيل بالرب، لأنه كان تحت إمرة سيسرا تسع مئة مركبة حديدية، وقد اشتد في مضايقة بني إسرائيل عشرين سنة.","4:4":"وكانت دبورة زوجة لفيدوت امرأة نبية وقاضية لإسرائيل في ذلك الوقت،","4:5":"وكانت تعقد مجلس قضائها تحت نخلة دبورة بين الرامة وبيت إيل. فكان بنو إسرائيل يفدون إليها للقضاء.","4:6":"فأرسلت هذه واستدعت باراق بن أبينوعم من قادش نفتالي، وقالت له: «هذا هو أمر الرب إله إسرائيل إليك: اذهب وازحف إلى جبل تابور بعد أن تجند لك عشرة آلاف رجل من أبناء نفتالي وزبولون،","4:7":"فأجتذب سيسرا رئيس جيش يابين بمركباته إلى نهر قيشون وأظفرك به».","4:8":"فقال لها باراق: «إن ذهبت معي أذهب، وإن لم تذهبي فلا أذهب».","4:9":"فأجابت: «أذهب معك، غير أنه لن يكون لك فخر في الطريق التي أنت ماض فيها، لأن الرب يسلم سيسرا لامرأة». فنهضت دبورة ورافقت باراق إلى قادش.","4:10":"واستدعى باراق رجال زبولون ونفتالي إلى قادش، فانضم إليه عشرة آلاف رجل. وانطلقت دبورة معه أيضا.","4:11":"في ذلك الوقت كان حابر القيني من ذرية حوباب حمي موسى، قد انفرد عن بقية عشيرة القينيين وضرب خيامه إلى جوار شجرة بلوط في صعنايم القريبة من قادش.","4:12":"وأبلغوا سيسرا أن باراق بن أبينوعم قد صعد إلى جبل تابور.","4:13":"فحشد سيسرا مركباته الحديدية التسع مئة، وجميع جيشه الذي معه من حروشة الأمم حتى نهر قيشون.","4:14":"فقالت دبورة لباراق: «قم، لأن هذا هو اليوم الذي فيه يظفرك الرب بسيسرا. ألم يتقدمك الرب؟» فانحدر باراق من جبل تابور على رأس عشرة آلاف رجل.","4:15":"فأرعب الرب سيسرا وكل مركباته وسائر جيشه وقضى عليهم بحد السيف أمام باراق. فترجل سيسرا من مركبته وهرب على رجليه.","4:16":"فتعقب باراق المركبات والجيش إلى حروشة الأمم، وتم القضاء على كل جيش سيسرا بحد السيف فلم يسلم منهم حي.","4:17":"وأما سيسرا فهرب ماشيا إلى خيمة ياعيل امرأة حابر القيني الذي كان قد عقد اتفاق صلح بينه وبين يابين ملك حاصور.","4:18":"فخرجت ياعيل لاستقبال سيسرا قائلة: «تعال إلى خيمتي يا سيدي ولا تخف». فمال إلى خيمتها وغطته بلحاف.","4:19":"ثم قال لها: «اسقيني قليلا من الماء لأني قد عطشت». ففتحت زق اللبن وأسقته ثم غطته.","4:20":"وقال لها: «قفي بباب الخيمة، حتى إذا أقبل أحدهم وسألك: أهنا أحد؟ تقولين: لا».","4:21":"وما لبث أن غط في نوم ثقيل لشدة تعبه. فأخذت ياعيل امرأة حابر وتد الخيمة ومطرقة، وتسللت إليه ودقت الوتد في صدغه فنفذ إلى الأرض ومات.","4:22":"وإذا بباراق يطارد سيسرا، فخرجت ياعيل لاستقباله وقالت له: «تعال لأريك الرجل الذي تبحث عنه». فدخل إلى خيمتها، وإذا بسيسرا طريح ميتا والوتد نافذ في صدغه.","4:23":"في ذلك اليوم أخضع الرب يابين ملك كنعان لبني إسرائيل،","4:24":"واشتدت وطأة سطوة بني إسرائيل عليه وازدادت قوة حتى تمت إبادته كليا.","5:1":"وأنشدت دبورة وباراق بن أبينوعم في ذلك اليوم قائلين:","5:2":"باركوا الرب لأن الرؤساء تولوا زمام القيادة في إسرائيل ولأن الشعب انتدبوا أنفسهم متطوعين.","5:3":"فاسمعوا أيها الملوك، واصغوا أيها الأمراء، لأنني أنا أشدو للرب، وأغني لإله إسرائيل.","5:4":"يا رب، عندما خرجت من سعير وتقدمت من صحراء أدوم، ارتعدت الأرض، وسكبت السماء أمطارها، وقطرت السحب ماء.","5:5":"تزلزلت الأرض أمام الرب وارتعد جبل سيناء هذا من حضرة الرب إله إسرائيل.","5:6":"في أيام شمجر بن عناة، وفي أيام ياعيل هجر المسافرون الطرق المعروفة، ولجأوا إلى المسالك الملتوية.","5:7":"وتضاءل عدد سكان إسرائيل، إلى أن صارت دبورة أما لإسرائيل.","5:8":"عندما اختاروا آلهة أخرى نشبت حرب عند بوابات المدينة، ولم يشاهد ترس أو رمح مع أي من الأربعين ألفا من إسرائيل.","5:9":"قلبي مع قضاة إسرائيل الذين ضحوا بأنفسهم عن رضى من بين الشعب، فباركوا الرب.","5:10":"أيها الراكبون الأتن الشهب، الجالسون على طنافس سرجكم وأنتم أيها السائرون في الطريق، تجاوبوا.","5:11":"بأصوات المنشدين عند سواقي المياه يتغنون بانتصارات الرب وشعبه في إسرائيل، عندئذ ينزل شعب الرب إلى بوابات المدينة.","5:12":"استيقظي يا دبورة، استيقظي واهتفي بنشيد. قم يا باراق، وخذ سبيك إلى الأسر، يا ابن أبينوعم.","5:13":"عندئذ أقبل الناجون إلى النبلاء؛ انحدر شعب الرب والتف حولي لمحاربة الأشداء.","5:14":"أقبل بعضهم من أرض أفرايم حيث أصولهم بين عماليق، وفي أعقابهم جاء شعب بنيامين. من ماكير تقدم قضاة، ومن زبولون أقبل حاملو عصا القيادة.","5:15":"جاء رؤساء يساكر مع دبورة وأخلصوا لباراق، فاقتحموا الوادي في أعقابه. أما أبناء رأوبين فقد اعتراهم التخاذل والحيرة.","5:16":"لماذا تخلفتم في حظائركم؟ ألتسمعوا صفير الرعاة إلى القطعان؟ لشد ما تسام عشائر رأوبين من عذاب الضمير.","5:17":"أقام جلعاد شرقي الأردن، وأنت يا دان لماذا استوطنت عند السفن؟ وبقي أشير قابعا عند ساحل البحر، وانطوى عند خلجانه.","5:18":"أما زبولون ونفتالي فقد عرضا حياتهما للموت عند روابي الحقل.","5:19":"احتشد ملوك وحاربوا، حارب ملوك كنعان في تعنك بجوار مياه مجدو، ولكنهم لم يغنموا قطعة فضة واحدة.","5:20":"من السماء حاربت النجوم سيسرا من مساراتها.","5:21":"وفاضت مياه نهر قيشون القديم وجرفت رجاله؛ فتقدمي يا نفسي بعز.","5:22":"ثم تردد وقع حوافر خيل العدو، من عدو الجياد الضخمة.","5:23":"غير أن ملاك الرب قال: «العنوا ميروز. العنوا ساكنيها بمرارة، لأنهم لم يأتوا للمحاربة في صف الرب ضد الجبابرة.","5:24":"لتكن ياعيل زوجة حابر القيني مباركة. لتكن مباركة أكثر من كل النساء ساكنات الخيام.","5:25":"فقد سألها سيسرا ماء فأعطته لبنا، قدمت له زبدة في وعاء العظماء.","5:26":"ثم تناولت وتد الخيمة بيد، ومدت يمينها إلى المطرقة وضربت سيسرا فسحقت رأسه وشدخت صدغه وخرقته!","5:27":"فانطرح عند قدميها. سقط، وظل ملقى هناك. انطرح عند قدميها وسقط. وحيث انطرح سقط قتيلا.","5:28":"من الكوة أشرفت أم سيسرا، ومن وراء النافذة المشبكة ولولت: لماذا أبطأت مركباته عن المجيء؟ لماذا تأخر صرير وقع مركباته؟","5:29":"فأجابتها أحكم نسائها، بل هي أجابت نفسها:","5:30":"«ألم يجدوا الغنيمة ويقتسموها؟ فتاة أو فتاتين لكل رجل، وغنيمة ثياب مصبوغة لسيسرا، وأخرى مصبوغة ومطرزة الوجهين لتكون غنيمة ألف بها عنقي؟.","5:31":"هكذا ينقرض جميع أعدائك يا رب، أما أحباؤك فهم كالشمس المتألقة في جبروتها». ثم خيم السلام على البلاد فترة أربعين سنة.","6:1":"وعاد بنو إسرائيل يقترفون الإثم في عيني الرب فسلط عليهم المديانيين سبع سنوات.","6:2":"واشتدت وطأة المديانيين على إسرائيل حتى لجأ الإسرائيليون إلى الجبال ليعيشوا في الكهوف والمغائر.","6:3":"وكلما زرع بنو إسرائيل زرعا جاء الناهبون المديانيون والعمالقة وسواهم من أبناء المشرق لينهبوا محاصيلهم،","6:4":"فيغزونهم ويتلفون غلات أرضهم حتى تخوم غزة ولا يتركون للإسرائيليين ما يقتاتون به، ويستولون أيضا على الغنم والبقر والحمير.","6:5":"لأنهم كانوا يغزون البلاد بمواشيهم وخيامهم، فكانوا في كثرة الجراد، لا يحصى لهم ولا لجمالهم عدد، فيغزون الأرض ويتلفونها.","6:6":"فأذل المديانيون الإسرائيليين جدا، فاستغاث هؤلاء بالرب.","6:7":"وعندما استغاث بنو إسرائيل بالرب من ظلم المديانيين،","6:8":"أرسل الرب نبيا إلى بني إسرائيل وقال لهم: «هذا ما يقوله الرب إله إسرائيل: لقد أخرجتكم من مصر وحررتكم من نير العبودية.","6:9":"وأنقذتكم من قبضة المصريين ومن يد جميع مضايقيكم، وطردتهم من وجهكم ووهبتكم أرضهم.","6:10":"وقلت لكم: أنا الرب إلهكم. لا تخافوا آلهة الأموريين الذين أنتم مقيمون في أرضهم، لكنكم لم تطيعوا قولي».","6:11":"ثم جاء ملاك الرب إلى قرية عفرة، وجلس تحت شجرة البلوط التي يملكها يوآش الأبيعزري. وكان ابنه جدعون يخبط حنطة في المعصرة لكي يهربها من المديانيين.","6:12":"فتجلى له ملاك الرب وقال له: «الرب معك أيها المحارب الجبار».","6:13":"فقال له جدعون: «دعني أسألك يا سيدي: إن كان الرب معنا، فلماذا أصابنا كل هذا البلاء؟ وأين كل عجائبه التي حدثنا بها آباؤنا قائلين: ألم يخرجنا الرب من مصر؟ والآن قد نبذنا الرب وجعلنا في قبضة مديان».","6:14":"فالتفت إليه الرب وأجاب: «اذهب بما تملكه من قوة وأنقذ إسرائيل من قبضة المديانيين. ألست أنا الذي أرسلك؟»","6:15":"فأجاب جدعون: «دعني أسألك يا سيدي: كيف أنقذ إسرائيل وعشيرتي هي أضعف عشائر سبط منسى، وأنا أقل أفراد عائلتي شأنا؟»","6:16":"فقال له الرب: «سأكون معك فتقضي على المديانيين وكأنك تقضي على رجل واحد».","6:17":"فقال له: «إن كنت حقا قد حظيت برضاك، فأعطني علامة أنك أنت الذي تخاطبني.","6:18":"أرجوك ألا تمضي من هنا حتى أرجع وأضع تقدمتي أمامك». فأجابه: «سأبقى حتى ترجع».","6:19":"فدخل جدعون إلى بيته وأعد جديا وإيفة دقيق فطيرا، ووضع اللحم في سل والحساء في قدر، وحملها إليه تحت البلوطة وقدمها له.","6:20":"فقال الملاك له: «خذ اللحم والفطير، وضعهما فوق تلك الصخرة واسكب الحساء» ففعل جدعون ذلك.","6:21":"فمد ملاك الرب طرف العكاز الذي بيده ومس به اللحم والفطير، فاندلعت نار من الصخرة والتهمتهما. وتوارى ملاك الرب عن عينيه.","6:22":"وعندما تبين جدعون أنه ملاك الرب، هتف مرتعبا: «آه يا سيدي الرب! لقد رأيت ملاك الرب وجها لوجه».","6:23":"فقال له الرب: «السلام لك، لا تخف، فأنت لن تموت.","6:24":"فبنى جدعون هناك مذبحا للرب سماه: يهوه شلوم (ومعناه: الرب سلام). ومازال المذبح قائما إلى هذا اليوم في عفرة الأبيعزريين.","6:25":"وقال الرب لجدعون في تلك الليلة: «خذ ثورا كامل النضج من قطيع أبيك: وثورا ثانيا عمره سبع سنوات، واهدم مذبح البعل الذي يعبده أبوك، واقطع نصب عشتاروث الذي إلى جواره.","6:26":"وابن مذبحا للرب إلهك على رأس تلك الصخرة، ورتب حجارته في المكان المعد، وخذ الثور وأصعده محرقة على خشب النصب الذي قطعته».","6:27":"عندئذ أخذ جدعون عشرة رجال من عبيده ونفذ ليلا ما أمره الرب به، لأنه كان يخشى غضب بيت أبيه وأهل المدينة، فلم يجرؤ على فعل ذلك نهارا.","6:28":"وفي فجر اليوم التالي اكتشف أهل المدينة أن مذبح البعل متهدم والنصب الذي إلى جواره مقطوع، والثور الثاني قد أصعد على المذبح الجديد.","6:29":"فسأل الواحد صاحبه: «من صنع هذا الأمر؟» وبعد بحث وتحر، اكتشفوا أن جدعون بن يوآش هو الجاني.","6:30":"فقال أهل المدينة ليوآش: «أخرج ابنك. يجب أن يموت لأنه هدم مذبح البعل وقطع النصب الذي إلى جواره».","6:31":"فقال يوآش لجميع الثائرين عليه: «أعازمون أنتم على الدفاع عن البعل؟ أم أنتم تحاولون إنقاذه؟ إن من يقاتل دفاعا عن البعل حتما يموت في هذا الصباح (لأن ذلك إهانة للبعل). إن كان البعل حقا إلها فليقاتل عن نفسه لأن مذبحه قد هدم».","6:32":"ومنذ ذلك اليوم دعي جدعون يربعل، لأن يوآش قال: «ليقاتله بعل»؛ لأن جدعون قد هدم مذبحه.","6:33":"وتحالفت جيوش مديان وعماليق وسواهم من أبناء المشرق وعسكروا في وادي يزرعيل.","6:34":"وحل روح الرب على جدعون فنفخ البوق فانضم إليه رجال أبيعزر.","6:35":"وأرسل جدعون مبعوثين إلى أسباط منسى وأشير وزبولون ونفتالي يستدعي قواتهم المحاربة، فخفوا إليه.","6:36":"وقال جدعون لله: «إن كنت حقا ستنقذ إسرائيل على يدي كما وعدت (فأعطني علامة على ذلك):","6:37":"سأضع الليلة جزة صوف في البيدر، فإن ابتلت الجزة وحدها بالندى، وبقيت الأرض كلها جافة، أدرك أنك تنقذ إسرائيل على يدي كما وعدتني».","6:38":"وهذا ما حدث: فعندما بكر جدعون في الصباح التالي أخذ جزة الصوف وضغطها وعصرها فقطر منها ملء قصعة من الماء.","6:39":"فقال جدعون لله: «لا يحتدم غضبك علي ودعني أتقدم مرة أخرى فقط بطلب واحد. اسمح لي أن أجري اختبارا آخر على هذه الجزة. لتبق هذه الجزة وحدها جافة، أما بقية الأرض فليبللها الندى».","6:40":"فصنع الرب ذلك. في تلك الليلة ابتلت الأرض كلها بالندى وبقيت الجزة وحدها جافة.","7:1":"وفي الصباح الباكر توجه يربعل (جدعون) وجيشه إلى عين حرود وخيموا هناك. وكان جيش المديانيين معسكرا إلى الشمال منهم في الوادي عند تل مورة.","7:2":"وقال الرب لجدعون: «إن القوم الذين معك كثيرون علي لطرد المديانيين بيدهم، لئلا يتباهى علي الإسرائيليون قائلين: إن قوتنا أنقذتنا.","7:3":"والآن ناد في مسامع القوم قائلا: كل من هو خائف ومرتعد فليرجع منصرفا من جبل جلعاد». فرجع من القوم اثنان وعشرون ألفا وبقي عشرة آلاف.","7:4":"وقال الرب لجدعون: «لم يزل عدد المحاربين كبيرا. انزل بهم إلى الماء فأغربلهم لك. فيذهب معك من أختاره لك وتصرف عنك من أرفضه.","7:5":"فنزل جدعون بالجيش إلى الماء. وقال الرب لجدعون: «كل من يلعق بلسانه من الماء كما يلعق الكلب أوقفه وحده، وكل من جثا على ركبتيه للشرب أوقفه وحده أيضا».","7:6":"فكان عدد الذين غرفوا الماء بأيديهم ولعقوه ثلاث مئة رجل. وأما باقي الجيش فجثوا على ركبهم لشرب الماء.","7:7":"فقال الرب لجدعون: «سأخلصكم وأظفرك بالمديانيين بالثلاث مئة رجل الذين لعقوا الماء. ولينصرف سائر القوم إلى أماكن سكناهم.","7:8":"فصرف جدعون بقية الإسرائيليين إلى خيامهم بعد أن أخذ مؤونتهم وأبواقهم، واحتفظ فقط بالثلاث مئة رجل. وكان مخيم المديانيين تحتهم في الوادي.","7:9":"وقال الرب في تلك الليلة لجدعون: «قم وهاجم المعسكر، لأنني مزمع أن أسلمه إلى يدك","7:10":"وإن كنت خائفا من مهاجمة المعسكر فتسلل أنت وفورة غلامك إليه،","7:11":"واستمع إلى حديثهم، فتتشدد عزيمتك وتهجم على المعسكر». فتسلل هو وفورة خادمه وكمن عند طرف المعسكر قريبا من مقر آخر المتجندين.","7:12":"وكان المديانيون والعمالقة وسائر بني المشرق مخيمين في الوادي، في كثرة الجراد، وجمالهم لا تحصى كالرمل الذي على شاطئ البحر.","7:13":"ولما وصل جدعون إلى مكمنه سمع رجلا يحدث صاحبه بحلم رآه قائلا: «رأيت في حلمي وإذا رغيف خبز شعير يتدحرج في معسكر المديانيين حتى بلغ الخيمة فضربها فسقطت، وقلبها رأسا على عقب».","7:14":"فأجاب صاحبه: «ليس ذلك سوى سيف جدعون بن يوآش قائد جيش إسرائيل، لقد أظفره الله على المديانيين وعلى كل الجيش».","7:15":"فلما سمع جدعون حديث الحلم وتفسيره سجد، ورجع إلى مخيم إسرائيل وقال: «هبوا، فقد نصركم الرب على جيش المديانيين».","7:16":"وقسم الثلاث مئة رجل إلى ثلاث فرق، ووزع على كل منهم بوقا وجرة فارغة في وسطها مصباح.","7:17":"وقال لهم: «انظروا إلي وافعلوا مثلي. عندما أبلغ طرف المعسكر، افعلوا تماما كما أفعل.","7:18":"ومتى نفخت أنا وكل الذين معي بالبوق، انفخوا أنتم أيضا بالأبواق حول كل المعسكر وقولوا: «للرب ولجدعون».","7:19":"فأقبل جدعون وفرقته إلى طرف المعسكر في منتصف الليل، بعد تغيير نوبة الحراسة، فنفخوا بالأبواق وحطموا الجرار التي بأيديهم.","7:20":"وهكذا نفخت الفرق الثلاث بالأبواق وحطموا الجرار وأمسكوا المصابيح بأيديهم اليسرى والأبواق بأيديهم اليمنى لينفخوا بها صارخين: «سيف للرب ولجدعون».","7:21":"ووقف كل منهم في مكانه حول المعسكر، فدب الذعر في الجيش وتراكضوا هاربين صارخين.","7:22":"وعادت الفرق الثلاث تنفخ في أبواقها، فجعل الرب أعداءهم يقاتلون بعضهم بعضا، وأغمد كل واحد سيفه في صاحبه وفروا إلى بيت شطة باتجاه صردة حتى بلغوا آبل محولة بالقرب من طباة.","7:23":"فاستدعى جدعون رجال إسرائيل من نفتالي ومن أشير ومن كل منسى وتعقبوا المديانيين.","7:24":"وبعث جدعون برسل إلى كل جبل أفرايم قائلا: «انزلوا للقاء المديانيين واستولوا على مواقع عبور نهر الأردن عند بيت بارة». فاحتشد كل رجال أفرايم واستولوا على مياه الأردن عند بيت بارة،","7:25":"وأسروا قائدي المديانيين غرابا وذئبا، فقتلوا غرابا على صخرة غراب، وأما ذئب فقتلوه عند معصرة ذئب. وتعقبوا المديانيين ثم حملوا رأسي غراب وذئب إلى جدعون عبر نهر الأردن.","8:1":"وخاصم رجال أفرايم جدعون خصاما شديدا قائلين له: «لماذا عاملتنا هكذا؟ لماذا لم تدعنا عند ذهابك لمحاربة المديانيين؟»","8:2":"فأجابهم: «أي شيء فعلته أنا يوازي ما أنجزتموه أنتم؟ أليست لقاطة عنب أفرايم خيرا من قطاف أبيعزر؟","8:3":"لقد أوقع الرب غرابا وذئبا قائدي المديانيين في أيديكم. فأي شيء استطعت أن أفعله يوازي عملكم هذا؟» وعندما سمعوا حديثه هدأت سورة غضبهم.","8:4":"واجتاز جدعون ورجاله الثلاث مئة نهر الأردن وقد نال منهم الإعياء من مطاردتهم للعدو.","8:5":"فقال لأهل سكوت: «أعطوا رجالي طعاما فإنهم منهكون، وأنا مازلت أطارد زبح وصلمناع ملكي مديان».","8:6":"فأجابه رؤساء سكوت: «ألعل زبح وصلمناع قد وقعا أسيرين في يدك الآن حتى نقدم لرجالك خبزا؟»","8:7":"فقال جدعون: «حسنا! عندما ينصرني الرب عليهما سأدرس بالنوارج لحمكم مع أشواك البرية».","8:8":"وتوجه من هناك إلى فنوئيل وطلب من أهلها طعاما، فأجابوه بمثل ما أجاب به أهل سكوت.","8:9":"فتوعدهم قائلا: «عند رجوعي بسلام سأهدم هذا البرج».","8:10":"وكان زبح وصلمناع معسكرين في قرقر على رأس جيش من نحو خمسة عشر ألفا هم البقية الباقية من جميع جيش أبناء المشرق بعد أن سقط منهم مئة وعشرون ألف رجل من المقاتلين بالسيوف.","8:11":"وسلك جدعون طريق ساكني الخيام شرقي نوبح ويجبهة وهاجم الجيش المدياني على حين غرة","8:12":"فهرب زبح وصلمناع فتعقبهما وقبض عليهما وشتت الجيش كله.","8:13":"ورجع جدعون بن يوآش من الحرب عن طريق عقبة حارس.","8:14":"وقبض على شاب من أهل سكوت وطلب منه أن يسجل له أسماء رؤساء سكوت وشيوخها. فسجل سبعة وسبعين اسما.","8:15":"ثم أقبل جدعون على أهل سكوت قائلا: «هوذا زبح وصلمناع اللذان عيرتموني بهما قائلين: ألعل زبح وصلمناع قد وقعا أسيرين لديك الآن حتى نقدم لرجالك المنهوكين خبزا؟»","8:16":"وقبض على شيوخ المدينة، وأخذ أشواكا من البرية ونوارج وعاقب بها أهل سكوت، فكان ذلك درسا لهم.","8:17":"وهدم برج فنوئيل وقتل رجال المدينة.","8:18":"وسأل جدعون زبح وصلمناع: «ما هيئة الرجال الذين قتلتماهم في تابور؟» فأجابا: «إنهم يشبهونك كل واحد منهم مثل ابن ملك».","8:19":"فقال: هم إخوتي أبناء أمي، حي هو الرب، ما كنت لأقتلكما لو أبقيتماهم أحياء».","8:20":"وقال ليثر ابنه البكر: «قم اقتلهما». ولكن هذا خاف أن يستل سيفه لأنه كان صغير السن.","8:21":"فقال زبح وصلمناع: «قم أنت واقتلنا، فخير لنا أن يقتلنا رجل» فقتلهما جدعون. وأخذ الحلي التي كانت تزين أعناق جمالهما.","8:22":"وقال بنو إسرائيل لجدعون: «تسلط علينا أنت وابنك وحفيدك، لأنك قد أنقذتنا من المديانيين»","8:23":"فأجابهم: «لا أتسلط عليكم، لا أنا ولا ابني، إنما الرب يتسلط عليكم.","8:24":"ولكن لي لديكم طلبة، وهي أن يعطيني كل واحد أقراط غنيمته، وهي أقراط الذهب التي يتحلى بها عادة الإسماعيليون» (الذين شكلوا جيش المديانيين).","8:25":"فأجابوه: «يسرنا أن نقدمها لك». وفرشوا رداء ألقى عليه كل واحد أقراط غنيمته.","8:26":"فكان وزن أقراط الذهب التي طلبها ألفا وسبع مئة شاقل (نحو عشرين كيلو جراما)، ما عدا الأهلة والحلق والأثواب الأرجوانية التي كان يرتديها ملوك مديان، والقلائد التي كانت تزين أعناق جمالهم.","8:27":"فصاغ منها جدعون صنما نصبه في مدينته عفرة، فغوى الإسرائيليون وراءه وعبدوه فكان هذا الصنم شركا لجدعون وعائلته.","8:28":"وذل المديانيون أمام بني إسرائيل ولم يعودوا يتطاولون عليهم. وعم السلام البلاد أربعين سنة طوال حياة جدعون.","8:29":"ورجع جدعون بن يوآش إلى بيته حيث أقام فيه.","8:30":"وكان لجدعون سبعون ولدا جميعهم من صلبه لأنه كان مزواجا.","8:31":"وولدت له أيضا سريته التي في شكيم ابنا دعاه أبيمالك.","8:32":"ومات جدعون بن يوآش بعد عمر طويل صالح، ودفن في قبر يوآش أبيه في عفرة، بلدة الأبيعزريين.","8:33":"ورجع بنو إسرائيل بعد موت جدعون وغووا وراء البعليم، واتخذوا بعل بريث إلها لهم،","8:34":"ونسوا الرب إلههم الذي أنقذهم من قبضة جميع أعدائهم المحيطين بهم.","8:35":"وأساءوا إلى بيت يربعل (جدعون) رغم كل الخير الذي أسداه إلى إسرائيل.","9:1":"ومضى أبيمالك بن يربعل إلى شكيم لزيارة أخواله وقال لعشيرة أمه:","9:2":"«اسألوا جميع أهل شكيم: أيهما أفضل لهم: أن يحكمهم سبعون رجلا هم أبناء يربعل، أم أن يتسلط عليهم رجل واحد؟ وتذكروا أنني من لحمكم وعظمكم».","9:3":"فشرع أخواله يدعون له بين أهل شكيم حتى استمالوا قلوبهم وراء أبيمالك قائلين: «هو أخونا».","9:4":"وأعطوه سبعين شاقل فضة (نحو ثمانية كيلو جرامات ونصف) من معبد بعل بريث استأجر بها أتباعا من الأوغاد الطائشين،","9:5":"واقتحم بهم بيت أبيه في عفرة، حيث ذبح إخوته السبعين على حجر واحد، ولم ينج إلا يوثام بن يربعل الأصغر الذي تمكن من الاختباء.","9:6":"فاجتمع أهل شكيم وجميع سكان القلعة ونصبوا أبيمالك ملكا عند بلوطة النصب الذي في شكيم.","9:7":"وبلغ الخبر يوثام فذهب ووقف على قمة جبل جرزيم ونادى بصوت مرتفع قائلا لهم: «أنصتوا لي يا أهل شكيم حتى يستمع لكم الله.","9:8":"ذات مرة ذهبت الأشجار لتنصب عليها ملكا، فقالت للزيتونة: «املكي علينا».","9:9":"فأجابت الزيتونة: «أأتخلى عن زيتي الذي يكرمون به الله والناس لكي أملك على الأشجار؟».","9:10":"فقالت الأشجار للتينة: «تعالي أنت واملكي علينا».","9:11":"فأجابت التينة: «أأهجر حلاوتي وثمري الطيب لأصير ملكة على الأشجار؟».","9:12":"فقالت الأشجار للكرمة: «تعالي أنت واملكي علينا».","9:13":"فأجابتهن الكرمة: «أأنبذ خمري الذي يفرح الله والناس لكي أملك على الأشجار؟»","9:14":"ثم قالت جميع الأشجار للعوسج: «تعال أنت وصر علينا ملكا»","9:15":"فقال العوسج: «إن كنتم حقا تنصبونني عليكم ملكا، فتعالوا واحتموا تحت ظلي، وإلا فإن نارا تندلع من العوسج وتلتهم أرز لبنان».","9:16":"والآن، إن كنتم قد تصرفتم بحق وصواب عندما ملكتم عليكم أبيمالك، وإن كنتم قد أحسنتم إلى يربعل وإلى أهل بيته فكافأتموه خيرا على عمل يديه.","9:17":"فقد حارب أبي عنكم وجازف بحياته وأنقذكم من قبضة المديانيين.","9:18":"أما أنتم فقد ثرتم اليوم على بيت أبي وذبحتم أبناءه السبعين على حجر واحد، وملكتم أبيمالك ابن جاريته على أهل شكيم لأنه أخوكم.","9:19":"فإن كنتم قد تصرفتم بحق وصواب مع يربعل وأهل بيته في هذا اليوم، فهنيئا لكم بأبيمالك وهنيئا له بكم.","9:20":"وإلا فلتندلع نار من أبيمالك وتلتهم أهل شكيم وسكان القلعة، ولتندلع نار من أهل شكيم ومن سكان القلعة وتلتهم أبيمالك».","9:21":"ثم هرب يوثام إلى مدينة بئر خوفا من أخيه، وأقام هناك.","9:22":"وتسلط أبيمالك على إسرائيل فترة ثلاث سنوات.","9:23":"وما لبث الرب أن جعل العلاقة تسوء بين أبيمالك وأهل شكيم، فخان أهل شكيم أبيمالك،","9:24":"عقابا له لما جناه من ظلم بحق أبناء يربعل السبعين الذين سفك دماءهم، وانتقاما من أهل شكيم الذين آزروه على ذبح إخوته.","9:25":"فنصب أهل شكيم لأبيمالك كمينا على قمم الجبال وراحوا ينهبون كل عابري الطريق. فأبلغ أبيمالك بالأمر.","9:26":"وجاء جعل بن عابد مع إخوته إلى شكيم فوثق به أهلها.","9:27":"ثم خرجوا إلى الحقول وجنوا غلات كرومهم وصنعوا منها خمرا، واحتفلوا ودخلوا إلى معبد إلههم وأكلوا وشربوا ولعنوا أبيمالك.","9:28":"فقال جعل بن عابد: «من هو أبيمالك ومن هو شكيم حتى نخدمه؟ أما هو ابن يربعل وزبول هو وكيله؟ اخدموا رجال حمور أبي شكيم. لماذا علينا أن نخدم أبيمالك؟","9:29":"لو صار هذا الشعب تحت إمرتي لعزلت أبيمالك، ولقلت له: جهز جيشك واخرج».","9:30":"وعندما سمع زبول رئيس المدينة كلام جعل بن عابد، احتدم غضبه.","9:31":"وبعث برسل إلى أبيمالك في ترمة قائلا: «قد وفد جعل بن عابد وإخوته إلى مدينة شكيم، وأثاروا المدينة ضدك.","9:32":"فالآن قم ليلا أنت ومن معك من الجيش واكمن في الحقل،","9:33":"وفي الصباح عند شروق الشمس تبكر باقتحام المدينة. وعندما يخرج جعل ومن معه من المحاربين لقتالك تفعل به كما تشاء».","9:34":"فجد أبيمالك وجيشه في السير ليلا وانقسموا في فرق أربع، وكمنوا لأهل شكيم.","9:35":"وعندما خرج جعل بن عابد ووقف عند مدخل بوابة المدينة تحرك أبيمالك ورجاله من مكامنهم.","9:36":"فرآهم جعل، فقال لزبول: «هوذا رجال منحدرون من قمم الجبال». فأجابه زبول: «إنك ترى ظلال الجبال وكأنها رجال».","9:37":"فعاد جعل يقول أيضا: «هوذا رجال منحدرون من المرتفعات، وها هي فرقة قادمة عن طريق بلوطة العائفين».","9:38":"فأجابه زبول: «أين هو تبجحك الآن حين قلت: من هو أبيمالك حتى نخدمه؟ أليس هؤلاء هم الرجال الذين سخرت منهم؟ فاخرج الآن وحاربه!».","9:39":"فخرج جعل في طليعة أهل شكيم وحارب أبيمالك.","9:40":"غير أنه انهزم أمامه وسقط عدد غفير من القتلى على طول الطريق إلى بوابة المدينة.","9:41":"واستقر أبيمالك في أرومة، وطرد زبول جعلا وإخوته من شكيم.","9:42":"وفي اليوم التالي خرج أهل شكيم إلى الحقل للحرب، فأبلغ أبيمالك بالأمر،","9:43":"فقسم جيشه إلى ثلاث فرق وكمن في الحقل، وإذا بأهل شكيم قد برزوا من المدينة فانقض عليهم وكسرهم.","9:44":"واقتحم أبيمالك وفرقته طريقه إلى مدخل بوابة المدينة وتمركز هناك. وهاجمت الفرقتان الأخريان كل من كانوا في الحقل وأبادتاهم.","9:45":"وظلت رحى الحرب دائرة طوال ذلك اليوم حتى استولى أبيمالك على المدينة وقضى على أهلها وهدمها وزرعها ملحا.","9:46":"وحين بلغ الخبر أهل برج شكيم تحصنوا في قلعة معبد إيل بريث.","9:47":"فعلم أبيمالك أن جميع أهل برج شكيم قد تحصنوا في القلعة،","9:48":"فارتقى هو وجيشه جبل صلمون، وأخذ فأسا بيده وقطع غصن شجرة ورفعه ووضعه على كتفه، وقال لرجاله: «كل ما ترونني أفعله فأسرعوا وافعلوا مثلي».","9:49":"فقطع كل واحد من الجيش غصنا وساروا خلف أبيمالك إلى القلعة حيث كوموا الأغصان وأحرقوا القلعة بمن فيها. فمات جميع أهل برج شكيم وكانوا نحو ألف رجل وامرأة.","9:50":"ثم توجه أبيمالك إلى تاباص وهاجمها واستولى عليها.","9:51":"فلجأ جميع الرجال والنساء وسائر أهل المدينة إلى برج حصين قائم في وسط المدينة، وأغلقوا أبوابه خلفهم، وصعدوا إلى سطح البرج.","9:52":"فحاصر أبيمالك البرج وحاربه، واقترب من باب البرج ليحرقه بالنار،","9:53":"فألقت امرأة حجر رحى على رأسه فشجت جمجمته.","9:54":"فاستدعى على التو حامل سلاحه وقال له: «اخترط سيفك واقتلني لئلا يقولوا عني: قتلته امرأة». فطعنه بالسيف فمات.","9:55":"فلما رأى رجال أبيمالك أن قائدهم قد مات انصرف كل منهم إلى مكانه.","9:56":"وهكذا عاقب الله أبيمالك على جريمته التي ارتكبها بحق أبيه حين قتل إخوته السبعين.","9:57":"وكذلك رد الله شر أهل شكيم على رؤوسهم، وبذلك تحققت لعنة يوثام بن يربعل.","10:1":"وقام بعد موت أبيمالك تولع بن فواة بن دودو من سبط يساكر لإنقاذ إسرائيل، وكان هذا قاطنا في شامير في جبل أفرايم،","10:2":"وظل قاضيا لإسرائيل مدة ثلاث وعشرين سنة، ثم مات ودفن في شامير.","10:3":"ثم تولى بعده قضاء إسرائيل يائير الجلعادي طوال اثنتين وعشرين سنة.","10:4":"وكان ليائير ثلاثون ابنا يركبون على ثلاثين جحشا ويملكون ثلاثين مدينة في أرض جلعاد، وهي تدعى حووث يائير إلى هذا اليوم.","10:5":"ثم مات يائير ودفن في قامون.","10:6":"وعاد بنو إسرائيل يرتكبون الإثم في عيني الرب، وعبدوا البعليم وعشتاروث وآلهة أرام وآلهة صيدون وآلهة بني عمون وآلهة الفلسطينيين وتركوا الرب ولم يعبدوه.","10:7":"واحتدم غضب الرب على إسرائيل وسلط عليهم الفلسطينيين وبني عمون،","10:8":"مدة ثماني عشرة سنة، فأذاقوا الإسرائيليين المقيمين في أرض الأموريين في جلعاد. شرقي نهر الأردن، سوء العذاب","10:9":"وعبر العمونيون نهر الأردن لمحاربة أسباط يهوذا وبنيامين وأفرايم، فاعترى الإسرائيليين ضيق عظيم.","10:10":"فاستغاثوا بالرب قائلين: «لقد أخطأنا إليك لأننا تركنا إلهنا وعبدنا البعليم».","10:11":"فأجابهم الرب: «ألم أنقذكم من المصريين والأموريين وبني عمون والفلسطينيين؟","10:12":"وعندما استغثتم بي من الصيدونيين والعمالقة والعمونيين الذين ضايقوكم، ألم أخلصكم؟","10:13":"أما أنتم فقد تركتموني وعبدتم آلهة أخرى، لهذا لا أعود أنقذكم،","10:14":"فهيا استجيروا بالآلهة التي اخترتموها لتخلصكم في وقت ضيقكم».","10:15":"فقال بنو إسرائيل للرب: «لقد أخطأنا، فافعل بنا ما تشاء، ولكن أنقذنا في هذا اليوم».","10:16":"وأزالوا الأوثان الغريبة من وسطهم وعبدوا الرب، فرق قلبه لمشقة إسرائيل.","10:17":"فاحتشد العمونيون وعسكروا في جلعاد، وتجمع بنو إسرائيل وخيموا في المصفاة.","10:18":"فتداول قادة إسرائيل في ما بينهم قائلين: «من يبدأ في شن الهجوم على العمونيين، يصبح رئيسا على جميع سكان جلعاد».","11:1":"وكان يفتاح الجلعادي محاربا شديد البأس، أنجبه أبوه جلعاد من امرأة عاهرة.","11:2":"وأنجب جلعاد أيضا عددا من الأبناء من زوجته، فلما كبروا طردوا يفتاح قائلين له: «أنت ابن عاهرة، ولن ترث شيئا من بيت أبينا».","11:3":"فهرب يفتاح من إخوته وأقام في أرض طوب، فاجتمع إليه رجال بطالون وتبعوه.","11:4":"وبعد زمن، حارب بنو عمون إسرائيل،","11:5":"فمضى شيوخ جلعاد ليأتوا بيفتاح من أرض طوب،","11:6":"وقالوا له: «تعال وكن قائدا لنا في حربنا مع العمونيين».","11:7":"فأجابهم يفتاح: «ألم تبغضوني وتطردوني من بيت أبي؟ فما بالكم تأتون إلي في ضيقتكم؟»","11:8":"فأجابوه: «لأننا في ضيق جئنا إليك لترجع معنا وتحارب بني عمون، وتكون رئيسا على كل سكان جلعاد».","11:9":"فقال لهم: «إن أرجعتموني لمحاربة بني عمون وهزمهم الرب أمامي، فهل حقا تجعلونني رئيسا عليكم؟»","11:10":"فأجابوه: «الرب شاهد بيننا إن كنا لا نفعل حسب قولك».","11:11":"فانطلق يفتاح مع شيوخ جلعاد فنصبه الشعب عليهم رئيسا وقائدا، وردد يفتاح تعهداته أمام الرب في المصفاة.","11:12":"ثم بعث يفتاح رسلا إلى ملك عمون يسأله: «ماذا تضمر ضدنا حتى أتيت لتهاجمنا في بلادنا؟»","11:13":"فأجاب ملك عمون رسل يفتاح: «لأن إسرائيل قد استولى على أرضي عند خروجه من مصر من أرنون إلى يبوق حتى نهر الأردن. والآن ردها من غير حرب».","11:14":"فعاد يفتاح فبعث رسلا إلى ملك بني عمون،","11:15":"قائلين له: «هذا ما يجيبك به يفتاح: إن بني إسرائيل لم يستولوا على أرض موآب ولا على أرض بني عمون،","11:16":"لأنه عند خروجهم من مصر ساروا في الصحراء حتى بلغوا البحر الأحمر وأتوا إلى قادش.","11:17":"ثم بعث الإسرائيليون رسلا إلى ملك أدوم يقولون له: دعنا نجتاز في أرضك. فلم يأذن لهم ملك أدوم. ثم بعثوا رسلا أيضا إلى ملك موآب فرفض هو الآخر. فمكث الإسرائيليون في قادش.","11:18":"ثم داروا في الصحراء ملتفين حول أرض أدوم وأرض موآب قادمين من الشرق إلى أرض موآب، وخيموا وراء حدود أرنون، ولم يعبروا إلى تخم موآب لأن أرنون هي حد موآب.","11:19":"بعد ذلك بعث بنو إسرائيل رسلا إلى سيحون ملك الأموريين في عاصمته حشبون يقولون: دعنا نعبر في أرضك إلى حيث نحن متوجهون.","11:20":"ولكن سيحون لم يأمن أن يعبر الإسرائيليون في أرضه، بل حشد كل جيشه وعسكر في ياهص وحارب بني إسرائيل.","11:21":"فنصر الرب إله إسرائيل شعبه على سيحون وجيشه، فهزموهم واستولوا على كل أرض الأموريين سكان تلك البلاد.","11:22":"فامتلكوا كل بلاد الأموريين من أرنون في الجنوب إلى اليبوق في الشمال، ومن الصحراء في الشرق إلى نهر الأردن في الغرب.","11:23":"والآن وقد طرد الرب إله إسرائيل الأموريين من أمام شعبه إسرائيل،","11:24":"فبأي حق تريد أنت أن تستردها؟ ألست تحتفظ بما أعطاه لك كموش إلهك؟ ونحتفظ نحن أيضا بما أعطاه لنا الرب إلهنا؟","11:25":"ثم هل أنت أفضل من بالاق بن صفور ملك موآب؟ هل خاصم بني إسرائيل أو أثار عليهم حربا؟","11:26":"لقد أقام بنو إسرائيل في حشبون وقراها، وعروعير وقراها وكل المدن التي على محاذاة نهر أرنون ثلاث مئة سنة، فلماذا لم تستردها طوال تلك الحقبة؟","11:27":"إنني لم أسئ إليك، أما أنت فترتكب شرا في حقي بإثارتك الحرب علي. فليكن الرب اليوم قاضيا بين بني إسرائيل وبين بني عمون».","11:28":"فلم يأبه ملك بني عمون لرسالة يفتاح.","11:29":"فحل روح الرب على يفتاح، فاجتاز أراضي جلعاد ومنسى ومصفاة جلعاد، ومنها تقدم نحو بني عمون.","11:30":"ونذر يفتاح نذرا للرب وقال: «إن نصرتني على بني عمون،","11:31":"فإنني عند رجوعي سالما من محاربة بني عمون أصعد للرب محرقة: أول من يخرج من أبواب بيتي للقائي».","11:32":"ثم تقدم يفتاح لمحاربة بني عمون، فأظفره الرب بهم،","11:33":"وهزمهم هزيمة منكرة من عروعير حتى منيت على امتداد عشرين مدينة إلى آبل الكروم. وهكذا أخضع بنو إسرائيل العمونيين.","11:34":"ثم رجع يفتاح إلى بيته في المصفاة، فخرجت ابنته الوحيدة، إذ لم يكن له ابن أو ابنة سواها، للقائه بدفوف ورقص.","11:35":"فلما رآها مزق ثيابه وولول قائلا: «آه يا ابنتي، لقد أحزنتني وحطمتني، لأنني نذرت نذرا للرب ولا سبيل للرجوع عنه».","11:36":"فأجابته: «لقد نذرت نذرك للرب، فافعل بي كما نذرت، ولاسيما أن الرب قد انتقم لك من أعدائك بني عمون».","11:37":"ثم قالت لأبيها: «ولكن حقق لي هذا الطلب: أمهلني شهرين أتجول فيهما في الجبال وأندب عذراويتي مع صاحباتي».","11:38":"فقال لها: «اذهبي». وأمهلها شهرين قضتهما هي وصاحباتها على الجبال تندب عذراويتها.","11:39":"ثم رجعت في نهاية الشهرين إلى أبيها، فأصعدها محرقة وفاء بنذره، فماتت عذراء،","11:40":"فصار من عادة الإسرائيليات أن يذهبن إلى الجبال أربعة أيام في السنة لينحن على ابنة يفتاح الجلعادي.","12:1":"وجهز سبط أفرايم جيشا، وتقدموا شمالا نحو زفون قائلين ليفتاح: «لماذا انطلقت لمحاربة العمونيين من غير أن تدعونا للانضمام إليك؟ لنحرقن عليك بيتك بالنار».","12:2":"فأجابهم: «كنت أنا وقومي في خصام عنيف مع العمونيين، فاستنجدت بكم فلم تجيروني.","12:3":"وعندما رأيت تقاعسكم عن إجارتي جازفت بحياتي، وحاربت بني عمون، فنصرني الرب عليهم. فلماذا اجتمعتم علي اليوم لمحاربتي؟»","12:4":"وحشد يفتاح كل رجال جلعاد وحارب سبط أفرايم وهزمهم، لأن رجال أفرايم استخفوا بالجلعاديين قائلين: «إنهم منبوذو أفرايم ومنسى».","12:5":"فاستولى الجلعاديون على مخاوض نهر الأردن، وكلما قال أحد رجال أفرايم الهاربين: «دعوني أعبر»، كان رجال جلعاد يسألونه: «أأنت أفرايمي؟» فإن قال: «لا»","12:6":"كانوا يطلبون منه أن يقول: «شبولت» فيقول: «سبولت» من غير أن يتحفظ في لفظها لفظا صحيحا، فيقبضون عليه ويذبحونه على مخاوض الأردن. فقتل في ذلك الوقت من أفرايم إثنان وأربعون ألفا.","12:7":"وظل يفتاح قاضيا في إسرائيل ست سنوات. وعندما مات دفن في إحدى مدن جلعاد.","12:8":"وخلف إبصان من بيت لحم، يفتاح قاضيا لإسرائيل.","12:9":"وكان له ثلاثون ابنا وثلاثون ابنة فزوج بناته من غير أبناء عشيرته، كما زوج أبناءه من غير بنات عشيرته، واستمر قاضيا لإسرائيل سبع سنوات.","12:10":"ثم مات إبصان ودفن في بيت لحم.","12:11":"وأعقبه في القضاء لإسرائيل إيلون الزبولوني، فظل قاضيا مدة عشر سنوات.","12:12":"ثم مات إيلون الزبولوني فدفن في إيلون في أرض سبط زبولون.","12:13":"وجاء بعده عبدون بن هليل الفرعتوني.","12:14":"وكان له أربعون ابنا وثلاثون حفيدا يركبون على سبعين حمارا. هذا قضى لإسرائيل ثماني سنوات.","12:15":"ثم مات عبدون بن هليل الفرعتوني ودفن في فرعتون في أرض أفرايم في جبل العمالقة.","13:1":"ثم عاد بنو إسرائيل يرتكبون الإثم في عيني الرب، فأسلمهم لقبضة الفلسطينيين أربعين سنة.","13:2":"وكان هناك رجل من بلدة صرعة من عشيرة الدانيين يدعى منوح، وامرأته عاقر لم تنجب.","13:3":"فتجلى ملاك الرب للمرأة وقال لها: «إنك عاقر لم تنجبي، ولكنك ستحبلين وتلدين ابنا.","13:4":"إنما إياك أن تشربي خمرا أو مسكرا أو تأكلي شيئا محرما","13:5":"لأنك ستحملين وتنجبين ابنا. فلا تحلقي شعر رأسه لأن الصبي يكون نذيرا لله من مولده، وهو يشرع في إنقاذ إسرائيل من تسلط الفلسطينيين","13:6":"فأسرعت إلى زوجها وقالت: «ظهر لي رجل من عند الله، ومنظره كهيئة ملاك الرب مجلل بالرهبة. لم أسأله من أين جاء، ولا هو أخبرني عن اسمه،","13:7":"وقال لي: ها أنت ستحبلين وتلدين ابنا، فإياك أن تشربي خمرا ولا مسكرا، ولا تأكلي شيئا محرما، لأن الصبي يكون نذيرا للرب منذ مولده حتى يوم وفاته».","13:8":"فتضرع منوح إلى الرب قائلا: «أتوسل إليك يا سيدي أن ترسل إلينا رجل الله الذي بعثته، ليعلمنا كيف نربي الصبي الذي يولد».","13:9":"فاستجاب الله صلاة منوح، فتجلى ملاك الله أيضا للمرأة وهي جالسة في الحقل، ولم يكن زوجها منوح معها.","13:10":"فأسرعت وأخبرت زوجها قائلة: «تراءى لي الرجل الذي ظهر لي في ذلك اليوم».","13:11":"فهب منوح في إثر زوجته حتى قدم على الرجل وسأله: «أأنت الرجل الذي خاطب زوجتي من قبل؟» فأجابه: «أنا هو».","13:12":"فقال منوح: «عندما يتحقق كلامك فكيف ينبغي أن نقوم بتربية الصبي ومعاملته؟»","13:13":"فأجابه الملاك: «لتحرص المرأة على طاعة كل ما أمرتها به.","13:14":"وإياها أن تأكل من كل نتاج الكرمة أو تشرب خمرا أو مسكرا، أو تأكل طعاما محرما. لتحرص على إطاعة كل ما أوصيتها به».","13:15":"فقال له منوح: «نود أن تمكث معنا ريثما نجهز لك جديا».","13:16":"فأجاب ملاك الرب: «ولو أعقتني لن آكل من خبزك، وإن قربت محرقة فللرب قدمها». ولم يكن منوح يدرك أن الرجل هو ملاك الرب.","13:17":"فسأل منوح ملاك الرب: «ما اسمك حتى إذا تحقق كلامك نكرمك؟»","13:18":"فأجاب: «لماذا تسأل عن اسمي وهو عجيب؟»","13:19":"ثم أخذ منوح جديا وتقدمة حبوب وقربهما على الصخرة للرب. فقام الملاك بعمل عجيب على مشهد من منوح وزوجته","13:20":"فقد صعد في ألسنة اللهيب المرتفعة من المذبح نحو السماء على مشهد منهما، فخرا على الأرض ساجدين.","13:21":"ولم يتجل ملاك الرب ثانية لمنوح وزوجته. عندئذ أدرك منوح أنه ملاك الرب.","13:22":"فقال منوح لامرأته: «إننا لابد مائتان لأننا قد رأينا الله»","13:23":"فأجابته: «لو أراد الرب أن يميتنا لما قبل منا محرقة وتقدمة، ولما أرانا كل هذه الأمور وأخبرنا بها في هذا الوقت».","13:24":"فأنجبت المرأة ابنا دعته شمشون. وكبر الصبي وباركه الرب.","13:25":"وابتدأ روح الرب يحركه في أرض سبط دان بين صرعة وأشتأول.","14:1":"وذهب شمشون إلى تمنة حيث راقته فتاة من بنات الفلسطينيين","14:2":"فرجع إلى والديه وأخبرهما قائلا: «راقتني امرأة في تمنة من بنات الفلسطينيين فزوجاني منها».","14:3":"فقال له والداه: «ألم تجد بين بنات أقربائك وفي قومنا فتاة، حتى تذهب وتتزوج من بنات الفلسطينيين الغلف؟» فأجاب شمشون أباه: «هذه هي الفتاة التي راقتني فزوجني إياها».","14:4":"ولم يدرك والداه أن ذلك الأمر كان من الرب، الذي كان يلتمس علة ضد الفلسطينيين الذين كانوا آنئذ متسلطين على إسرائيل.","14:5":"فانحدر شمشون ووالداه إلى تمنة حتى بلغوا كرومها، وإذا بشبل أسد يتحفز مزمجرا للانقضاض عليه،","14:6":"فحل عليه روح الرب فقبض على الأسد وشقه إلى نصفين وكأنه جدي صغير، من غير أن يكون معه سلاح. ولم ينبئ والديه بما فعل.","14:7":"ثم مضى إلى الفتاة وخاطبها فازداد بها إعجابا.","14:8":"وعندما رجع شمشون بعد أيام ليتزوج منها مال ليلقي نظرة على جثة الأسد، فوجد في جوفها سربا من النحل وبعض العسل،","14:9":"فتناول منه قدرا على كفه ومضى وهو يأكل. ثم أقبل على والديه فأعطاهما فأكلا، ولم يخبرهما أنه اشتار العسل من جوف الأسد.","14:10":"وذهب والده إلى بيت العروس، فأقام شمشون هناك وليمة كما تقتضي أعراف الزواج.","14:11":"ودعا الفلسطينيون ثلاثين شابا لينادموه (في فترة الاحتفال بزواجه).","14:12":"فقال لهم شمشون: «سألقي عليكم أحجية، فإن وجدتم حلها الصحيح في سبعة أيام الوليمة أعطيكم ثلاثين قميصا وثلاثين حلة ثياب.","14:13":"أما إن عجزتم عنها فستعطوني أنتم ثلاثين قميصا وثلاثين حلة ثياب». فقالوا له: «هات أحجيتك فنسمعها».","14:14":"فقال لهم: «من الآكل خرج أكل، ومن القوي خرجت حلاوة». وانقضت ثلاثة أيام من غير أن يجدوا لها حلا.","14:15":"وفي اليوم الرابع قالوا لزوجة شمشون: «تملقي زوجك ليكشف لنا عن حل الأحجية، لئلا نضرم النار فيك وفي بيت أبيك. أدعوتمونا إلى الوليمة لتسلبونا؟»","14:16":"فبكت امرأة شمشون لديه قائلة: «أنت تمقتني ولا تحبني حقا. فقد طرحت على بني قومي أحجية ولم تطلعني على حلها». فقال لها: «هوذا أبي وأمي لم أطلعهما على حلها، فلماذا أخبرك أنت به؟»","14:17":"فظلت تبكي لديه طوال سبعة أيام الوليمة. وفي اليوم السابع أطلعها على الحل لفرط ما ضايقته، فأسرت به لبني قومها.","14:18":"وقبل غروب شمس اليوم السابع قال له رجال المدينة: «أي شيء أحلى من العسل، وما هو أقوى من الأسد؟» فقال لهم شمشون: «لولا أنكم حرثتم على عجلتي لما وجدتم حل أحجيتي».","14:19":"وحل عليه روح الرب فانحدر إلى مدينة أشقلون وقتل ثلاثين رجلا منهم، وأخذ ثيابهم وأعطاها للرجال الذين حلوا لغزه. ولكن، إذ احتدم غضبه مضى إلى بيت والديه.","14:20":"وما لبثت امرأة شمشون أن أصبحت زوجة لصاحبه الذي كان نديما له.","15:1":"وحدث بعد مدة في موسم حصاد القمح، أن شمشون أخذ جديا وذهب ليزور زوجته،","15:2":"وقال لحميه: «أنا داخل إلى مخدع زوجتي». ولكن أباها منعه وقال: «لقد ظننت أنك كرهتها فزوجتها لنديمك. فلماذا لا تتزوج أختها الأصغر منها عوضا عنها؟ أليست هي أجمل منها؟»","15:3":"فأجابه شمشون: «لا لوم علي هذه المرة إذا انتقمت من الفلسطينيين».","15:4":"وانطلق شمشون واصطاد ثلاث مئة ثعلب وربط ذيلي كل ثعلبين معا ووضع بينهما مشعلا،","15:5":"ثم أضرم المشاعل بالنار وأطلق الثعالب بين زروع الفلسطينيين، فأحرقت حقول القمح وأكداس الحبوب وأشجار الزيتون.","15:6":"فسأل الفلسطينيون: «من الجاني؟» فقيل لهم: «شمشون صهر التمني، لأنه أخذ امرأة شمشون وزوجها لنديمه»، فصعد الفلسطينيون وأحرقوها مع أبيها بالنار.","15:7":"فقال شمشون: «لأنكم هكذا تتصرفون فإنني لن أكف حتى أنتقم منكم».","15:8":"وهجم عليهم بضراوة وقتل منهم كثيرين، ثم ذهب إلى مغارة صخرة عيطم وأقام فيها.","15:9":"فتقدم جيش الفلسطينيين واحتلوا أرض يهوذا وانتشروا في لحي","15:10":"فسألهم رجال يهوذا: «لماذا جئتم لمحاربتنا؟» فأجابوهم: «جئنا لكي نأسر شمشون ونفعل به مثلما فعل بنا».","15:11":"فذهب ثلاثة آلاف رجل من سبط يهوذا إلى مغارة صخرة عيطم وقالوا لشمشون: «ألا تعلم أن الفلسطينيين متسلطون علينا، فماذ فعلت بنا؟» فأجابهم: «كما فعلوا بي هكذا فعلت بهم».","15:12":"فقالوا له: «لقد جئنا لنوثقك ونسلمك إلى الفلسطينيين». فقال لهم شمشون: «احلفوا لي أن لا تقتلوني بأنفسكم».","15:13":"فأجابوه: «لا، لن نقتلك نحن، إنما نوثقك ونسلمك إليهم». فأوثقوه بحبلين جديدين وأخرجوه من المغارة.","15:14":"فلما وصل إلى لحي هب الفلسطينيون صارخين للقائه، فحل عليه روح الرب، وقطع الحبلين اللذين على ذراعيه وكأنهما خيوط كتان محترقة.","15:15":"وعثر على فك حمار طري، تناوله وقتل به ألف رجل.","15:16":"ثم قال شمشون: «بفك حمار كومت أكداسا فوق أكداس، بفك حمار قضيت على ألف رجل».","15:17":"وعندما كف عن الكلام ألقى فك الحمار من يده، ودعا ذلك الموضع رمت لحي (ومعناه تل عظمة الفك).","15:18":"وعطش شمشون عطشا شديدا، فاستغاث بالرب قائلا: «لقد منحت هذا الخلاص العظيم على يد عبدك، فهل أموت الآن من العطش وأقع أسيرا في يد الغلف؟»","15:19":"ففجر الله له ينبوع ماء من فتحة في الأرض في لحي، فشرب منها وانتعشت نفسه. لذلك دعا اسم الموضع عين هقوري (ومعناه ينبوع الذي دعا). ومازال الينبوع في لحي إلى يومنا هذا.","15:20":"وظل شمشون قاضيا لإسرائيل عشرين سنة في أثناء حكم الفلسطينيين.","16:1":"وذات يوم ذهب شمشون إلى غزة حيث التقى بامرأة عاهرة فدخل إليها.","16:2":"فقيل لأهل غزة: «قد جاء شمشون إلى هنا». فحاصروا المنزل وكمنوا له الليل كله عند بوابة المدينة، واعتصموا بالهدوء في أثناء الليل قائلين: «عند بزوغ الصباح نقتله».","16:3":"وظل شمشون راقدا حتى منتصف الليل، ثم هب وخلع مصراعي بوابة المدينة بقائمتيها وقفلها، ووضعها على كتفيه وصعد بها إلى قمة الجبل مقابل حبرون.","16:4":"وبعد ذلك وقع شمشون في حب امرأة في وادي سورق اسمها دليلة،","16:5":"فجاء إليها أقطاب الفلسطينيين وقالوا لها: «تملقي شمشون إلى أن تكتشفي منه سر قوته العظيمة، وكيف يمكننا أن نتغلب عليه ونوثقه فنذله فيكافئك كل واحد منا بألف ومئة شاقل من الفضة (نحو مئة واثنين وثلاثين كيلو جراما)».","16:6":"فقالت دليلة لشمشون: «أخبرني ما هو سر قوتك العظيمة وكيف يتسنى تقييدك وإذلالك»","16:7":"فأجابها شمشون: «إذا أوثقوني بسبعة أوتار طرية لم تجف بعد، أصبح ضعيفا كأي واحد من الناس».","16:8":"فأحضر لها أقطاب الفلسطينيين سبعة أوتار طرية لم تجف بعد، فأوثقته بها.","16:9":"وكان الكمين متربصا به في حجرتها، فقالت له: «الفلسطينيون قادمون عليك يا شمشون». فقطع الأوتار وكأنها خيوط شيطتها النار، ولم يكتشف سر قوته.","16:10":"فقالت له دليلة: «لقد خدعتني وكذبت علي. فأخبرني الآن كيف توثق؟»","16:11":"فأجابها: «إذا أوثقوني بحبال جديدة، أصبح ضعيفا كأي واحد من الناس».","16:12":"فأخذت دليلة حبالا جديدة وأوثقته بها، وقالت له: «الفلسطينيون قادمون عليك يا شمشون». وكان الكمين يتربص به في الحجرة، فقطع الحبال عن ذراعيه وكأنها خيوط.","16:13":"فقالت دليلة لشمشون: «أنت مازلت تكذب علي وتخدعني، فأخبرني بماذا توثق؟» فأجابها: «إن ضفرت خصلات شعري السبع بمغزل وثبتها بوتد، فإنني أصبح ضعيفا كأي واحد من الناس. وبينما كان يغط في نوم عميق ضفرت دليلة خصلات شعره السبع بمغزل.","16:14":"وثبتتها بوتد، ونادته ثانية: «الفلسطينيون قادمون عليك يا شمشون» فانتبه من نومه وخلع وتد النسيج مع المغزل.","16:15":"فقالت له: «كيف تدعي أنك تحبني وقلبك لا يثق بي؟ قد خدعتني ثلاث مرات ولم تطلعني على سر قوتك العظيمة».","16:16":"وظلت تلح عليه وتزعجه كل يوم بمثل هذا الكلام حتى ضاقت نفسه إلى الموت.","16:17":"فكشف لها عن مكنون قلبه، وقال لها: «إنني نذير الرب منذ مولدي، لهذا لم أحلق شعري. وإن حلقته فإن قوتي تفارقني وأصبح ضعيفا كأي واحد من الناس».","16:18":"ولما أدركت دليلة أنه قد أسر لها بمكنون قلبه، استدعت أقطاب الفلسطينيين قائلة: «تعالوا هذه المرة، فقد أطلعني على سر قوته». فأقبل عليها أقطاب الفلسطينيين حاملين معهم الفضة.","16:19":"فأضجعته على ركبتيها واستدعت رجلا حلق له خصلات شعره السبع، وشرعت في إذلاله بعد أن فارقته قوته.","16:20":"وقالت: «الفلسطينيون قادمون عليك يا شمشون» فاستيقظ من نومه وقال: «أقوم مثل كل مرة وأنتفض». ولم يعلم أن الرب قد فارقه.","16:21":"فقبض عليه الفلسطينيون وقلعوا عينيه وأخذوه إلى غزة حيث أوثقوه بسلاسل نحاسية، وسخروه ليطحن الحبوب في السجن.","16:22":"وما لبث شعره أن ابتدأ ينمو بعد أن حلق.","16:23":"واجتمع أقطاب الفلسطينيين ليحتفلوا بتقديم ذبيحة عظيمة لإلههم داجون قائلين: «إن إلهنا قد أظفرنا بشمشون عدونا».","16:24":"ولما شاهد الشعب شمشون في ذلة، مجدوا إلههم قائلين: «قد أظفرنا إلهنا بعدونا الذي خرب أرضنا، وأكثر من قتلانا».","16:25":"وإذ لعبت بهم النشوة هتفوا: «ادعوا شمشون ليسلينا». فجاءوا بشمشون من السجن فلعب أمامهم ثم أوقفوه بين الأعمدة.","16:26":"فقال شمشون للغلام الذي يقوده: «أوقفني حيث يمكنني أن ألمس الأعمدة التي يقوم عليها المعبد حتى أستند إليها».","16:27":"وكان المعبد يكتظ بالرجال والنساء، فضلا عن أقطاب الفلسطينيين الخمسة. وكان على السطح نحو ثلاثة آلاف رجل وامرأة يتفرجون على لعب شمشون.","16:28":"فصلى شمشون إلى الرب قائلا: «يا سيدي الرب، اذكرني وقوني هذه المرة فقط لأنتقم من الفلسطينيين عن قلع عيني بضربة واحدة».","16:29":"وقبض شمشون على العمودين المتوسطين اللذين يرتكز عليهما المعبد وضغط على أحدهما بيمينه وعلى الآخر بيساره","16:30":"وهو يقول: «لأمت مع الفلسطينيين». ثم دفعهما بكل قوته فانهار المعبد على الأقطاب وعلى الشعب الذي فيه. فكان الذين قتلهم شمشون عند موته أكثر من الذين قتلهم طوال حياته.","16:31":"وجاء إخوته وكل أقرباء أبيه وحملوا جثته حيث دفنوه بين صرعة وأشتأول في قبر منوح أبيه، وكان شمشون قد قضى لبني إسرائيل عشرين سنة.","17:1":"وكان رجل اسمه ميخا مقيما في جبل أفرايم.","17:2":"قال هذا لأمه: «إن الألف والمئة شاقل من الفضة (نحو مئة واثنين وثلاثين كيلو جراما) التي سرقت منك، والتي سمعتك تلعنين سارقها، هي معي، وأنا الذي أخذتها». فقالت أمه: «ليباركك الرب يا ولدي».","17:3":"فرد لها الألف والمئة شاقل من الفضة، فقالت أمه: «سأهب هذا المال باسمك للرب، لننحت تمثالا ونصوغ منها صنما، وها أنا أرد لك المال».","17:4":"وأعطت أمه مئتي قطعة فضة للصائغ فنحت وصاغ لها تمثالين، نصبا في بيت ميخا.","17:5":"إذ كان ميخا قد خصص موضعا في بيته ليكون معبدا للآلهة. ثم صنع أفودا وترافيم، وكرس واحدا من بنيه كاهنا له.","17:6":"في تلك الأيام لم يكن لإسرائيل ملك، فكان كل واحد يتصرف على هواه.","17:7":"وكان هناك شاب لاوي من بيت لحم مقيما بين سبط يهوذا.","17:8":"هذا هاجر من مدينة بيت لحم ليتغرب في الأرض، فأتى إلى جبل أفرايم ومر في طريقه ببيت ميخا.","17:9":"فسأله ميخا: «من أين أتيت؟» فأجابه: «أنا لاوي من بيت لحم يهوذا، وأنا ذاهب لأتغرب حيثما اتفق».","17:10":"فقال له ميخا: «أقم عندي وكن لي مرشدا وكاهنا، وأنا أعطيك عشرة شواقل فضة (نحو مئة وعشرين جراما) في السنة وحلة ثياب فضلا عن القوت». فوافق اللاوي على عرضه،","17:11":"ورضي بالإقامة معه. وصار اللاوي أثيرا لديه كأحد أبنائه.","17:12":"فكرس ميخا اللاوي، فأصبح له كاهنا وأقام في بيته.","17:13":"فقال ميخا: «الآن علمت أن الرب راض عني، لأن اللاوي صار لي كاهنا».","18:1":"وفي تلك الأيام عندما لم يكن على إسرائيل ملك، شرع أبناء سبط دان يبحثون عن مكان يستوطنون فيه، لأنهم لم يكونوا قد ورثوا نصيبهم من الأرض بعد وسط أسباط إسرائيل.","18:2":"فأرسل الدانيون خمسة رجال من سبطهم من ذوي البأس في مدينتي صرعة وأشتأول، لتجسس الأرض واستكشافها، وقالوا لهم: «انطلقوا واستطلعوا لنا الأرض» فجاءوا إلى جبل أفرايم إلى بيت ميخا وقضوا ليلتهم هناك.","18:3":"وعرفوا من لهجة كاهن ميخا أنه من سبط لاوي، فانتحوا به جانبا وسألوه: «من جاء بك إلى هنا، وماذا تفعل في هذا المكان؟ ولماذا أنت هنا؟»","18:4":"فأجابهم: «كذا وكذا صنع لي ميخا، وقد استأجرني فأصبحت له كاهنا».","18:5":"فقالوا له: «اسأل إذن الله لنعلم إن كانت مهمتنا ستكلل بالنجاح أم لا».","18:6":"فقال لهم الكاهن: «اذهبوا بسلام فطريقكم التي تسلكونها تنعم برعاية الرب».","18:7":"فمضى الرجال الخمسة حتى وصلوا إلى لايش، فوجدوا أهلها الصيدونيين مقيمين فيها مطمئنين كعادة الصيدونيين، آمنين، لا يؤذيهم أحد في أرضهم، أثرياء ويتمتعون بالاكتفاء الذاتي، وكانوا بعيدين عن الصيدونيين، ولم يعقدوا أحلافا مع أحد.","18:8":"فعاد الرجال الخمسة إلى قومهم في صرعة وأشتأول، فسألوهم: «ماذا وجدتم؟»","18:9":"فأجابوهم: «هيا بنا نهجم على أهل لايش فأرضهم خصيبة، فما بالكم متقاعسون؟ لا تتكاسلوا عن الهجوم لامتلاك الأرض.","18:10":"فأنتم عندما تقدمون عليها ستجدون قوما مطمئنين في أرض شاسعة. إن الرب قد وهبها لكم وهي أرض خصيبة لا تفتقر إلى شيء».","18:11":"فارتحل من صرعة وأشتأول ست مئة رجل مدججين بالسلاح من سبط دان.","18:12":"وعسكروا في قرية يعاريم في يهوذا، فدعي ذلك الموضع مخيم دان إلى هذا اليوم، وهو يقع وراء قرية يعاريم.","18:13":"واجتازوا من هناك إلى جبل أفرايم وجاءوا إلى بيت ميخا.","18:14":"فقال الرجال الخمسة الذين ذهبوا لاستكشاف أرض لايش لقومهم: «أتعلمون أن في هذه البيوت أفودا وترافيم وتمثالا منحوتا وآخر مسبوكا، فانظروا ماذا تفعلون».","18:15":"فاتجهوا نحو البيوت وجاءوا إلى منزل الشاب اللاوي في بيت ميخا وسلموا عليه.","18:16":"وبقي الرجال الدانيون المسلحون الست مئة واقفين عند مدخل الباب","18:17":"فدخل الرجال الخمسة الذين ذهبوا لاستكشاف الأرض إلى موضع المعبد، وأخذوا التمثالين المنحوت والمسبوك والأفود والترافيم، بينما كان الكاهن واقفا عند مدخل الباب مع الست مئة رجل المدججين بالسلاح.","18:18":"وإذ رآهم الكاهن قد دخلوا بيت ميخا وأخذوا التمثالين المنحوت والمسبوك والأفود والترافيم، سألهم: «ماذا تفعلون؟»","18:19":"فقالوا له: «اصمت. لا تنطق بكلمة. تعال معنا وكن لنا مرشدا وكاهنا. أيهما خير لك: أن تكون كاهنا لبيت رجل واحد، أم تكون كاهنا لسبط وعشيرة في إسرائيل؟»","18:20":"فاغتبط قلب الكاهن للأمر، وأخذ الأفود والترافيم والتمثال المنحوت وانضم إلى القوم.","18:21":"ثم انطلقوا في طريقهم بعد أن جعلوا أطفالهم ومواشيهم ومؤونتهم في الطليعة.","18:22":"ولما ابتعدوا عن بيت ميخا تجمع رجال الحي الذي فيه بيت ميخا وتعقبوا أبناء دان حتى أدركوهم.","18:23":"وصاحوا بهم، فسأل الدانيون ميخا: «مالك تصرخ؟ وماذا يزعجك حتى تعقبتنا بهذه الشرذمة من المحاربين؟»","18:24":"فأجاب: «لقد أخذتم آلهتي التي صنعتها، وكذلك الكاهن، ومضيتم. فماذا بقي لي؟ فكيف تسألونني: مالك؟»","18:25":"فقال له الدانيون: «لا ترفع صوتك بيننا لئلا تثير غضب رجال أفظاظ الطباع فيهاجموك ويقتلوك مع أهل بيتك».","18:26":"وانطلق الدانيون في طريقهم. ولما رأى ميخا أنهم أقوى من أن يتغلب عليهم رجع إلى بيته.","18:27":"أما الدانيون فقد أقبلوا إلى لايش ومعهم أصنام ميخا والكاهن، فوجدوا شعبها آمنا مطمئنا مسالما، فهاجموها وقتلوا أهلها بحد السيف وأحرقوها.","18:28":"ولم يهب أحد لإنقاذها لأنها كانت بعيدة عن صيدون، ولم يعقد أهلها أحلافا مع أحد. وكانت المدينة تقع في الوادي الذي فيه بيت رحوب. وأعاد الدانيون بناء المدينة وأقاموا فيها،","18:29":"ودعوها دان باسم دان أبيهم الذي أنجبه إسرائيل، أما اسمها القديم فكان لايش.","18:30":"ونصب أبناء دان لأنفسهم التمثال المنحوت، وظل يهوناثان ابن جرشوم بن منسى وبنوه من بعده كهنة لسبط الدانيين إلى يوم سبي البلاد.","18:31":"ونصبوا تمثال ميخا المنحوت الذي صنعه، طوال الحقبة التي كان فيها بيت الله في شيلوه.","19:1":"وفي تلك الأيام التي لم يكن فيها ملك لبني إسرائيل، كان رجل لاوي متغربا في المنطقة النائية من جبل أفرايم، فاتخذ له محظية من بيت لحم يهوذا.","19:2":"ولكنها غضبت منه فلجأت إلى بيت أبيها في بيت لحم يهوذا حيث مكثت أربعة أشهر.","19:3":"ثم أخذ زوجها خادمه وحمارين وتوجه إلى بيت أبيها ليسترضيها، فدعته للدخول إلى بيت أبيها الذي سر بلقائه.","19:4":"وألح عليه والد الفتاة في البقاء، فمكث معه ثلاثة أيام حيث أكلوا جميعا وشربوا وقضوا لياليهم هناك.","19:5":"وفي اليوم الرابع قام مبكرا للذهاب، فقال والد الفتاة لصهره: «كل لقمة خبز تسند بها قلبك ومن ثم تمضون»","19:6":"فجلسا وأكلا وشربا معا، ثم قال له حموه: «إن راق لك الأمر، بت عندنا ولتطب نفسك».","19:7":"وعندما هم الرجل بالذهاب ألح عليه حموه، فرضخ وقضى ليلته هناك.","19:8":"ثم نهض في اليوم الخامس مبكرا تأهبا للرحيل، فقال أبو الفتاة: «تناول لقمة تسند بها قلبك، وانطلقوا عند الغروب». فبقي الرجل وأكلا معا.","19:9":"ثم هب الرجل للارتحال هو ومحظيته وغلامه. فقال له حموه: «لقد مالت الشمس إلى المغيب، فبيتوا هنا وليطب قلبك، وغدا ترحلون مبكرين نحو خيمتك».","19:10":"فأبى الرجل البقاء، وانطلقوا جميعا حتى جاءوا إلى مقابل يبوس التي هي أورشليم ومعه حماران مسرجان ومحظيته.","19:11":"وفيما هم بجوار يبوس وقد كاد النهار أن يغرب، قال الخادم لسيده: «تعال ندخل إلى مدينة اليبوسيين ونقضي ليلتنا فيها».","19:12":"فأجابه سيده: «لا، لن ندخل مدينة غريبة لا يقيم فيها إسرائيلي واحد، بل لنعبر إلى جبعة.","19:13":"دعنا نتابع تقدمنا فنبيت في جبعة أو الرامة».","19:14":"وواصلوا السير حتى بلغوا جبعة بنيامين عند غروب الشمس.","19:15":"فدخلوا إليها ليجدوا لهم مأوى فيها، وجلسوا في ساحة المدينة فلم يستضفهم أحد في بيته.","19:16":"وفيما هم كذلك أقبل عليهم عجوز قادم من العمل في حقله عند المساء. وكان الرجل أصلا من جبل أفرايم، متغربا في جبعة وأهل المدينة بنيامينيين.","19:17":"هذا وجدهم جالسين في ساحة المدينة، فسألهم: «إلى أين أنتم ذاهبون، ومن أين أتيتم؟»","19:18":"فأجابه الرجل المسافر: «نحن في طريقنا من بيت لحم يهوذا إلى الجانب النائي من جبل أفرايم حيث أقيم، وقد ذهبت إلى بيت لحم يهوذا، وأنا الآن متوجه إلى بيت الرب، وليس أحد يستضيفني في بيته،","19:19":"مع أن لدينا علفا وتبنا لحميرنا، وكذلك خبزا لي ولأمتك وللغلام، فلسنا في حاجة إلى شيء».","19:20":"فقال الشيخ: «أهلا بك في بيتي. لا تبت في الساحة، وأنا أقدم لك كل ما تحتاج إليه».","19:21":"واستضافهم في بيته وعلف حميرهم، فغسلوا أرجلهم وتناولوا طعاما وشرابا.","19:22":"وفيما هم يتنادمون إذا بجماعة من أوغاد المدينة يحاصرون البيت طارقين على الباب صائحين بالرجل الشيخ صاحب المنزل: «أخرج إلينا الرجل الذي استضفته لنعاشره»","19:23":"فخرج إليهم صاحب البيت وقال لهم: «لا يا إخوتي. لا ترتكبوا هذا العمل المشين، فالرجل ضيفي وقد دخل بيتي.","19:24":"هوذا ابنتي العذراء ومحظيته، فدعوني أخرجهما لكم فتمتعوا بهما وافعلوا ما يحلو لكم، ولكن لا ترتكبوا هذا العمل القبيح بهذا الرجل».","19:25":"غير أن الرجال الأوغاد رفضوا الاستماع إليه. فما كان من الرجل الضيف إلا أن أخرج لهم محظيته، فظلوا يتناوبون على اغتصابها طوال الليل حتى انبلاج الصباح، وعند بزوغ الفجر أطلقوها.","19:26":"وأقبلت المرأة عند طلوع الصباح إلى بيت الرجل الشيخ حيث سيدها مقيم، وتهالكت عند الباب حتى شروق النهار.","19:27":"فنهض سيدها في الصباح، وعندما فتح أبواب البيت وخرج لمتابعة طريقه عثر على محظيته ساقطة عند باب البيت، ويداها على العتبة.","19:28":"فقال لها: «انهضي لنذهب». فلم تجبه (لأنها كانت قد فارقت الحياة) فحملها على الحمار وانطلق إلى حيث يقطن.","19:29":"وما إن بلغ بيته حتى تناول سكينا، وشرع في تقطيع محظيته إلى اثنتي عشرة قطعة مع عظامها، ووزعها على جميع أسباط إسرائيل،","19:30":"فقال كل من شاهد إحدى هذه القطع: «لم يشهد أو يحدث مثل هذا الأمر منذ صعود بني إسرائيل من مصر إلى هذا اليوم. فتبصروا وتشاوروا واتخذوا قرارا».","20:1":"وخرج بنو إسرائيل جميعهم كرجل واحد قادمين من دان في الشمال إلى بئر سبع في الجنوب، ومن أرض جلعاد أيضا، ومثلوا أمام الرب في المصفاة.","20:2":"واحتشد زعماء الشعب مع أربع مئة ألف من محاربي أسباط إسرائيل.","20:3":"فبلغ النبأ سبط بنيامين أن المحاربين الإسرائيليين قد تجمعوا في المصفاة. وقال الإسرائيليون: «قصوا علينا كيف حدثت هذه القباحة؟»","20:4":"فأجاب زوج القتيلة: «دخلت أنا ومحظيتي إلى جبعة بنيامين لنقضي ليلتنا،","20:5":"فثار علي رجال من جبعة وحاصروني بالبيت ليلا، وهموا بقتلي واغتصبوا محظيتي حتى ماتت.","20:6":"فأخذتها وقطعتها ووزعتها في جميع أرض إسرائيل لأنهم ارتكبوا قباحة وفجورا في إسرائيل.","20:7":"والآن تبصروا بالأمر يا أبناء إسرائيل واحكموا».","20:8":"فهب المحاربون، كرجل واحد، وهتفوا: «لن يرجع أحد منا إلى خيمته أو بيته،","20:9":"قبل أن نعاقب أهل جبعة على ما اقترفوه. سنلقي قرعة","20:10":"لنختار عشرة رجال من كل مئة من محاربي كل سبط، ومئة من كل ألف، وألفا من كل عشرة آلاف للإشراف على تموين المحاربين بالمؤونة، بينما يقوم بقية الجيش بمعاقبة جبعة بنيامين على القباحة التي ارتكبتها في إسرائيل».","20:11":"وهكذا احتشد كل رجال إسرائيل ضد المدينة، واتحدوا كأنهم رجل واحد.","20:12":"وبعث أسباط بني إسرائيل إلى جميع عشائر بنيامين قائلين: «ما هذا الشر الذي تفشى بينكم؟","20:13":"لذلك، سلموا الأوغاد بني بليعال المقيمين في جبعة لكي نقتلهم ونستأصل الشر من إسرائيل». فأبى البنيامينيون الاستجابة إلى طلب إخوتهم بني إسرائيل.","20:14":"وتقاطروا من سائر المدن إلى جبعة تأهبا لمحاربة الإسرائيليين.","20:15":"وبلغ عدد محاربي بني بنيامين الوافدين من المدن في ذلك اليوم ستة وعشرين ألف محارب، فضلا عن أهل جبعة البالغين سبع مئة رجل من خيرة المحاربين.","20:16":"وكان من جملة جيش بنيامين سبع مئة رجل أعسر منتخبون لرمي الحجر بالمقلاع، لمهارتهم في إصابة الهدف من غير أن يخطئوا ولو بمقدار شعرة.","20:17":"أما جيش إسرائيل، باستثناء بنيامين، فقد بلغ عدده أربع مئة ألف، وكلهم رجال حرب.","20:18":"فانطلق هؤلاء إلى بيت إيل ليستشيروا الله قائلين: «من يذهب أولا لمحاربة بنيامين؟» فأجاب الرب: «يهوذا أولا».","20:19":"فبكر الإسرائيليون في الصباح وأحاطوا بجبعة.","20:20":"واصطف رجال إسرائيل متأهبين لمحاربة البنيامينيين عند جبعة.","20:21":"فاندفع بنو بنيامين نحوهم، وأهلكوا في ذلك اليوم اثنين وعشرين ألف رجل.","20:22":"وتشجع جيش إسرائيل، وعادوا فاصطفوا في نفس الموضع الذي اصطفوا فيه في اليوم الأول.","20:23":"وبكوا أمام الرب إلى المساء طالبين مشورته قائلين: «هل نعود لمحاربة إخوتنا بني بنيامين؟» فقال الرب: «اهجموا عليهم».","20:24":"فتقدم الإسرائيليون لمحاربة البنيامينيين في اليوم التالي.","20:25":"فاندفع البنيامينيون نحوهم وقتلوا منهم أيضا ثمانية عشر ألف رجل، وكلهم من المقاتلين بالسيف.","20:26":"فتوجه جميع الشعب من المحاربين إلى بيت إيل وبكوا ومثلوا أمام الرب صائمين في ذلك اليوم إلى المساء، ثم أصعدوا للرب محرقات وذبائح سلام.","20:27":"واستشار بنو إسرائيل الرب. وكان تابوت عهد الرب مازال آنئذ هناك.","20:28":"وفينحاس بن ألعازار بن هرون هو الكاهن الواقف على خدمته. وسأل بنو إسرائيل الرب: «هل نعود لمحاربة إخوتنا بني بنيامين أم نكف عن قتالهم؟» فأجاب الرب: «قاتلوهم لأني غدا أنصركم عليهم».","20:29":"ونصب الإسرائيليون كمينا حول جبعة،","20:30":"وتقدموا لمحاربة بني بنيامين واصطفوا عند جبعة كالمرتين الأوليين","20:31":"فاندفع البنيامينيون لمهاجمتهم، وابتعدوا عن المدينة وراء الإسرائيليين في الطريق المفضية إلى بيت إيل، والطريق الأخرى المؤدية إلى جبعة عبر الحقل، وشرعوا يهاجمون الجيش الإسرائيلي كالمرتين السابقتين، فقتلوا منهم نحو ثلاثين رجلا.","20:32":"واعتقد بنو بنيامين أن الإسرائيليين منهزمون أمامهم كما حدث سابقا، في حين أن بني إسرائيل تظاهروا بالهرب أمامهم قائلين: «لنجتذبهم بعيدا عن المدينة إلى الطرق».","20:33":"وهب رجال إسرائيل من أماكنهم واصطفوا في بعل تامار، ووثب كمين بني إسرائيل من مراصده من عراء جبعة.","20:34":"وتقدم عشرة آلاف رجل من خيرة محاربي إسرائيل من مقابل جبعة، فاشتدت المعركة من غير أن يدرك البنيامينيون أن الكارثة قد أحاقت بهم.","20:35":"وهزم الرب بنيامين أمام إسرائيل فأهلكوا منهم في ذلك اليوم خمسة وعشرين ألف رجل ومئة رجل، وكلهم من رجال السيف.","20:36":"عندئذ أدرك البنيامينيون أنهم قد هزموا. وكان الإسرائيليون قد تظاهروا بالتقهقر اعتمادا على الكمين الذي نصبوه حول جبعة.","20:37":"وما لبث الكمين أن اقتحم جبعة وضربها بحد السيف.","20:38":"وكان الاتفاق بين رجال إسرائيل وبين الكمين أن يصعد الكمين حال اقتحامه للمدينة عمودا متكاثفا من الدخان.","20:39":"فلما تقهقر الإسرائيليون في الحرب، شرع البنيامينيون في مطاردتهم فقتلوا منهم نحو ثلاثين رجلا، اعتقادا منهم أن الإسرائيليين منهزمون أمامهم كما حدث في المعارك الأولى.","20:40":"ولكن عندما ابتدأ عمود الدخان يتصاعد من المدينة التفت بنو بنيامين وراءهم وإذا بالدخان يرتفع نحو عنان السماء من كل أرجاء المدينة.","20:41":"فانكفأ رجال إسرائيل على البنيامينيين الذين فروا مرعوبين لأنهم أدركوا أن الكارثة قد أحاقت بهم.","20:42":"وتقهقروا أمام بني إسرائيل في طريق الصحراء. ولكن الحرب أدركتهم، وخرج رجال الكمين من المدن وقطعوا عليهم الطريق، فهلك البنيامينيون بين الفريقين.","20:43":"وهكذا حاصروا بني بنيامين وتعقبوهم بسهولة، وأدركوهم مقابل جبعة شرقا.","20:44":"فقتل منهم ثمانية عشر ألف رجل من جبابرة القتال.","20:45":"وعندما ولت فلولهم هاربة إلى الصحراء إلى صخرة رمون، تمكن الإسرائيليون من القضاء على خمسة آلاف منهم في الطريق، ثم جدوا في تعقبهم إلى جدعوم فقتلوا منهم أيضا ألفي رجل.","20:46":"فكانت جملة المقتولين من البنيامينيين في ذلك اليوم خمسة وعشرين ألف رجل من المحاربين بالسيف، وجميعهم جبابرة قتال.","20:47":"وتمكن ست مئة رجل منهم من الهرب واللجوء إلى صخرة رمون فأقاموا هناك أربعة أشهر.","20:48":"وارتد بنو إسرائيل إلى مدن بنيامين وقضوا على أهاليها قاطبة بحد السيف، وذبحوا البهائم وكل ما وجد فيها، وأحرقوها بالنار.","21:1":"وأقسم رجال إسرائيل في المصفاة ألا يزوج أحد منهم ابنته لأي رجل من سبط بنيامين.","21:2":"فاجتمعوا في بيت إيل ومثلوا أمام الرب باكين بمرارة حتى المساء،","21:3":"قائلين: «لماذا يا رب إله إسرائيل قد حدثت هذه الكارثة في إسرائيل حتى يفنى أحد أسباط إسرائيل؟»","21:4":"وبكر القوم في صباح اليوم التالي وبنوا هناك مذبحا قدموا عليه محرقات وذبائح سلام.","21:5":"وقال بنو إسرائيل: «هل تغيب أحد من أسباط إسرائيل عن حضور اجتماعنا أمام الرب في المصفاة، لأننا أقسمنا يمينا مغلظة أن نقتل كل من تغيب عن الحضور؟»","21:6":"واعترى الندم بني إسرائيل على إخوتهم بني بنيامين قائلين: «قد انقرض اليوم أحد أسباط إسرائيل","21:7":"فماذا نعمل للبقية الباقية منهم لنزوجهم، وقد حلفنا نحن بالرب ألا نعطيهم بناتنا؟».","21:8":"وتساءلوا: «أي سبط من أسباط إسرائيل لم يصعد للمثول أمام الرب في المصفاة؟» وتبينوا أن أحدا من يابيش جلعاد لم يحضر،","21:9":"لأنهم حين أحصوا الشعب وجدوا أن أهل يابيش جلعاد جميعهم قد تخلفوا عن الحضور.","21:10":"فأرسلت الجماعة حملة من اثني عشر ألف رجل من جبابرة القتال وأوصوهم قائلين: «انطلقوا واقضوا على أهل يابيش جلعاد بحد السيف رجالا ونساء وأطفالا.","21:11":"اقتلوا كل ذكر وكل امرأة عاشرت رجلا».","21:12":"فوجدوا بين أهل يابيش جلعاد أربع مئة فتاة عذراء فقط لم يضاجعن رجلا، فجاءوا بهن إلى المخيم إلى شيلوه التي في أرض كنعان.","21:13":"وبعثت الجماعة كلها بوفد وخاطبت أبناء بنيامين المعتصمين في صخرة رمون واستدعتهم للصلح.","21:14":"فرجع البنيامينيون آنئذ، فأعطوهم الفتيات اللواتي استحيوهن من بنات يابيش جلعاد فلم يكفينهم","21:15":"وانتاب الندم الشعب من أجل ما جرى لبنيامين، لأن الرب جعل ثغرة في أسباط إسرائيل.","21:16":"فقال شيوخ الجماعة: «كيف نحصل على زوجات لرجال بنيامين الباقين بعد أن انقرضت النساء من سبطهم،","21:17":"إذ يجب أن يكون ورثة للناجين من بني بنيامين، فلا ينقرض سبط من إسرائيل،","21:18":"لأننا نحن لا نقدر أن نزوجهم من بناتنا بعد أن أقسمنا قائلين: «ملعون من يزوج امرأة لرجل بنياميني».","21:19":"ثم قالوا: «هناك احتفال سنوي في شيلوه شمالي بيت إيل شرقي الطريق المتجهة من بيت إيل إلى شكيم وجنوبي لبونة.","21:20":"فأوصوا بني بنيامين قائلين: انطلقوا إلى الكروم واكمنوا فيها.","21:21":"وانتظروا حتى إذا خرجت بنات شيلوه للرقص فاندفعوا أنتم نحوهن، واخطفوا لأنفسكم كل واحد امرأة واهربوا بهن إلى أرض بنيامين.","21:22":"فإذا جاء آباؤهن أو إخوتهن لكي يشكوا إلينا نجيبهم: تعطفوا عليهم من أجلنا، لأننا لم نحصل على زوجة لكل واحد منهم في حربنا مع أهل يابيش جلعاد، وأنتم لم تزوجوهم من بناتكم عن طيب خاطر فتأثموا».","21:23":"وهكذا صنع رجال بنيامين، فقد اختطفوا العدد الكافي من الراقصات وتزوجوا منهن، ورجعوا إلى ديارهم وعمروا المدن وأقاموا فيها.","21:24":"ثم انطلق بنو إسرائيل، منذ ذلك الوقت، كل واحد إلى سبطه وعشيرته، عائدين إلى أرض ميراثهم.","21:25":"في تلك الأيام لم يكن ملك على إسرائيل، فكان كل واحد يعمل ما حسن في عينيه."};
